window.LQ_SOL=window.LQ_SOL||{};window.LQ_SOL["2014年第五届"]={"1429":[{"aid":"108529","title":"比较容易理解的代码","date":"2025-02-20","likes":0,"views":622,"md":"S 正文\n原题链接：蓝桥杯2014年第五届真题-兰顿蚂蚁\n\n解题思路:\n\n注意事项:\n\n参考代码:\n#include<bits/stdc++.h>\nusing namespace std;\nint a[105][105];\nvoid move(int &x, int &y, char &s, int &m, int &n, int a[105][105]) {\n    if (a[x][y] == 0 && s == 'L' && x < m) {\n        s = 'D';\n        a[x][y] = 1;\n        x += 1;\n    } else if (a[x][y] == 0 && s == 'D' && y < n) {\n        s = 'R';\n        a[x][y] = 1;\n        y += 1;\n    } else if (a[x][y] == 0 && s == 'R' && x > 1) {\n        s = 'U';\n        a[x][y] = 1;\n        x -= 1;\n    } else if (a[x][y] == 0 && s == 'U' && y > 1) {\n        s = 'L';\n        a[x][y] = 1;\n        y -= 1;\n    }\n\n    else if (a[x][y] == 1 && s == 'L' && x > 1) {\n        s = 'U';\n        a[x][y] = 0;\n        x -= 1;\n    } else if (a[x][y] == 1 && s == 'U' && y < n) {\n        s = 'R';\n        a[x][y] = 0;\n        y += 1;\n    } else if (a[x][y] == 1 && s == 'R' && x < m) {\n        s = 'D';\n        a[x][y] = 0;\n        x += 1;\n    } else if (a[x][y] == 1 && s == 'D' && y > 1) {\n        s = 'L';\n        a[x][y] = 0;\n        y -= 1;\n    }\n}\n\nint main()\n{\n\tint m,n;\n\tcin>>m>>n;\n\tfor(int i=1;i<=m;i++)\n\t{\n\tfor(int j=1;j<=n;j++)\n\t{\n\t\tcin>>a[i][j];\n\t}\n\t}\n\n\tint x,y,t;\n\tchar s;\n\tcin>>x>>y>>s>>t;\n\tx=x+1,y=y+1;\n\twhile(t--)\n\t{\n\t\tmove(x,y,s,m,n,a);\n\t}\n\tcout<<x-1<<\" \"<<y-1;\n \treturn 0;\n}\n\n E 正文"},{"aid":"107515","title":"兰顿蚂蚁普通思路","date":"2024-11-26","likes":2,"views":580,"md":"S 正文\n原题链接：蓝桥杯2014年第五届真题-兰顿蚂蚁\n\n解题思路:\n定义俩个方向数组\nint dx[] = {0, 1, 0, -1};\n int dy[] = {1, 0, -1, 0};\n\n注意事项:\n\n主要是定义方向的变量黑色方块(direction + 3) % 4，即顺时针转三次，如初始时刻direction=0，(direction + 3) % 4时等于3，dx[3]=-1,dy[3]=0向上移动;同理如果是白色方块顺时针一次direction = (direction + 1) % 4;然后通过k来控制循环次数。\n****注意输入时到字符串应该要有一个空格来输入scanf(\"%d%d %c%d\", &x, &y, &s, &k);\n 参考代码:\n#include <stdio.h>\nint main() {\n    int i, j, m, n, k, x, y;\n    char s;\n    scanf(\"%d%d\", &m, &n);\n    int arr[m][n];\n    for (i = 0; i < m; i++) {\n        for (j = 0; j < n; j++) {\n            scanf(\"%d\", &arr[i][j]);\n        }\n    }\n    scanf(\"%d%d %c%d\", &x, &y, &s, &k);\n    int direction = 0;\n    if (s == 'D') direction = 1;\n    else if (s == 'L') direction = 2;\n    else if (s == 'U') direction = 3;\n    int dx[] = {0, 1, 0, -1};\n    int dy[] = {1, 0, -1, 0};\n    while (k > 0) {\n        if (x < 0 || x >= m || y < 0 || y >= n) {\n            break;\n        }\n        if (arr[x][y] == 0) {\n            direction = (direction + 3) % 4;\n            arr[x][y] = 1;\n        } else {\n            direction = (direction + 1) % 4;\n            arr[x][y] = 0;\n        }\n        x += dx[direction];\n        y += dy[direction];\n        k--;\n    }\n    printf(\"%d %d\\n\", x, y);\n    return 0;\n}\n\n E 正文"},{"aid":"104602","title":"蓝桥杯2014年第五届真题-兰顿蚂蚁（python）","date":"2024-04-20","likes":0,"views":779,"md":"S 正文\n原题链接：蓝桥杯2014年第五届真题-兰顿蚂蚁\n\n解题思路:\n\n把蚂蚁的行动、动作当作对象，创建关于mayi（）的的对象，并对蚂蚁行动关于黑格、白格等转向设置函数point（self），在主函数中对行走后原位置黑白格取反注意事项:\n此代码中，每个格子的参数类型为str，如果是int型，会导致一直导致答案错误，还有在使用map_1时，与map函数很类似，可能导致程序出错\n参考代码\nclass mayi():\n   def __init__(self,head,x,y):\n       self.head=head\n       self.x=x\n       self.y=y\n   def point(self):\n       p=self.head\n       i=self.x\n       j=self.y\n       if p=='L':\n           if map_1[i][j]=='1':\n               self.x=i-1\n               self.head='U'\n           else:\n               self.x=i+1\n               self.head='D'\n       if p=='U':\n           if map_1[i][j]=='1':\n               self.y=j+1\n               self.head='R'\n           else:\n               self.y=j-1\n               self.head='L'\n       if p=='R':\n           if map_1[i][j]=='1':\n               self.x=i+1\n               self.head='D'\n           else:\n               self.x=i-1\n               self.head='U'\n       if p=='D':\n           if map_1[i][j]=='1':\n               self.y=j-1\n               self.head='L'\n           else:\n               self.y=j+1\n               self.head='R'\nm, n = map(int, input().split())\nmap_1 = []\nfor i in range(0, m):\n   map_1.append(list(input().split()))\nx,y,S,k=input().split()\nx=int(x)\ny=int(y)\nk=int(k)\nyi_1=mayi(S,x,y)\n\nfor w in range(0,k):\n   i=yi_1.x\n   j=yi_1.y\n   yi_1.point()\n   if map_1[i][j]=='1':\n       map_1[i][j] = '0'\n   elif map_1[i][j]=='0':\n       map_1[i][j] = '1'\nprint(yi_1.x,yi_1.y)\n\n E 正文"},{"aid":"103507","title":"蓝桥杯2014年第五届真题-兰顿蚂蚁","date":"2024-03-16","likes":1,"views":716,"md":"S 正文\n原题链接：蓝桥杯2014年第五届真题-兰顿蚂蚁\n\n解题思路:\n\n注意事项:\n\n参考代码:\n#include<iostream>\nusing namespace std;\nint main()\n{\n    int m,n;cin>>m>>n;\n    int a[m][n];\n    for(int i=0;i<m;i++)\n    {\n        for(int j=0;j<n;j++)\n            cin>>a[i][j];\n    }\n    int x,y,k; char s;   cin>>x>>y>>s>>k;\n    char U='U',D='D',L='L',R='R';            //注意\n    int sum=0;\n    while(sum<k)\n    {\n        if(s==L && x > 0 && a[x][y]==1)\n        {\n            a[x][y]=0;\n            x=x-1;\n            s=U;\n            sum++;\n            if(sum==k) break;\n        }\n        else if(s==L && x < m-1 && a[x][y]==0)\n        {\n            a[x][y]=1;\n            x=x+1;\n            s=D;\n            sum++;\n            if(sum==k) break;\n        }\n        else if(s==U && y < n-1 && a[x][y]==1)\n        {\n            a[x][y]=0;\n            y=y+1;\n            s=R;\n            sum++;\n            if(sum==k) break;\n        }\n        else if(s==U && y>0 && a[x][y]==0)\n        {\n            a[x][y]=1;\n            y=y-1;\n            s=L;\n            sum++;\n            if(sum==k) break;\n        }\n        else if(s==D && y > 0 && a[x][y]==1)\n        {\n            a[x][y]=0;\n            y=y-1;\n            s=L;\n            sum++;\n            if(sum==k) break;\n        }\n        else if(s==D && y <n-1 && a[x][y]==0)\n        {\n            a[x][y]=1;\n            y=y+1;\n            s=R;\n            sum++;\n            if(sum==k) break;\n        }\n        else if(s==R && x < m-1 && a[x][y]==1)\n        {\n            a[x][y]=0;\n            x=x+1;\n            s=D;\n            sum++;\n            if(sum==k) break;\n        }\n        else if(s==R && x > 0 && a[x][y]==0)\n        {\n            a[x][y]=1;\n            x=x-1;\n            s=U;\n            sum++;\n            if(sum==k) break;\n        }\n    }\n    cout<<x<<\" \"<<y;\n}\n\n E 正文"},{"aid":"97318","title":"直接拿捏...","date":"2023-07-11","likes":0,"views":684,"md":"S 正文\n原题链接：蓝桥杯2014年第五届真题-兰顿蚂蚁\n\n解题思路:\n\n注意事项:\n\n参考代码:\n#include<stdio.h>\n\nvoid direction(char *head,int line,int list,int array[line][list],int *i,int *j){\n    if(*head=='U'){\n        if(array[*i][*j]==0){\n            array[*i][*j] = 1;\n            (*j)--;\n            *head = 'L';\n        }else{\n            array[*i][*j] = 0;\n            (*j)++;\n            *head = 'R';\n        }\n        return;\n    }else if(*head == 'D'){\n        if(array[*i][*j]==0){\n            array[*i][*j] = 1;\n             (*j)++;\n             *head = 'R';\n        }else{\n            array[*i][*j] = 0;\n             (*j)--;\n             *head = 'L';\n        }\n        return;\n    }else if(*head == 'L'){\n         if(array[*i][*j]==0){\n            array[*i][*j] = 1;\n             (*i)++;\n             *head = 'D';\n        }else{\n            array[*i][*j] = 0;\n              (*i)--;\n             *head = 'U';\n        }\n        return;\n    }else{\n        if(array[*i][*j]==0){\n            array[*i][*j] = 1;\n             (*i)--;\n             *head = 'U';\n        }else{\n            array[*i][*j] = 0;\n              (*i)++;\n             *head = 'D';\n        }\n        return;\n    }\n}\n\nint main(void){\n    int line ,list,i,j;\n    scanf(\"%d %d\",&line,&list);\n    int array[line][list];\n    for(i=0;i<line;i++){\n        for(j=0;j<list;j++){\n            scanf(\"%d\",&array[i][j]);\n        }\n    }\n    int x,y,count;\n    char head;\n    scanf(\"%d %d %c %d\",&x,&y,&head,&count);\n    for (i=0;i<count;i++){\n        direction(&head,line,list,array,&x,&y);\n    }\n    printf(\"%d %d\",x ,y);\n    return 0;\n}\n\n E 正文"}],"1431":[{"aid":"109260","title":"C语言解分糖果","date":"2025-05-22","likes":0,"views":602,"md":"S 正文\n原题链接：蓝桥杯2014年第五届真题-分糖果\n\n解题思路:逐步分析，用计数器计算补的糖果数\n\n注意事项:这里将num[n]也放进去了，每次改变num[0]的值都要更新一次num[n]\n\n参考代码:\nint main()\n{\n\tint n;\n\tscanf(\"%d\", &n);\n\tint i;\n\tint num[100] = {0};\n\tfor(i=0;i<n;i++)\n\t{\n\t\tscanf(\"%d\", &num[i]);\n\t}\n\tnum[n] = num[0];\n\tint num1 = 0;\n\tint num2 = 0;\n\twhile (1)\n\t{\n\t\tnum2 = 0;\n\t\tfor (i = 0; i <= n; i++)\n\t\t{\n\t\t\tnum[i] = num[i] / 2 + num[i + 1] / 2;\n\t\t\tif (i == n)\n\t\t\t{\n\t\t\t\tnum[i] = num[0];\n\t\t\t}\n\t\t}\n\t\tfor (i = 0; i < n; i++)\n\t\t{\n\t\t\tif (num[i] % 2 == 1)\n\t\t\t{\n\t\t\t\tnum[i]++;\n\t\t\t\tnum1++;\n\t\t\t}\n\t\t}\n\t\tnum[n] = num[0];\n\t\tfor (i = 0; i < n; i++)\n\t\t{\n\t\t\tif(num[i]==num[i+1])\n\t\t\t{\n\t\t\t\tnum2++;\n\t\t\t}\n\t\t}\n\t\tif (num2 == n)\n\t\t\tbreak;\n\t}\n\tprintf(\"%d\\n\", num1);\n\treturn 0;\n}\n\n E 正文"},{"aid":"109028","title":"分糖果 —— 全网最简单的思路！","date":"2025-04-08","likes":0,"views":772,"md":"S 正文\n原题链接：蓝桥杯2014年第五届真题-分糖果\n\n解题思路：最简单的思路\n\n注意事项：列表的使用\n\n参考代码:\nn = int(input())\ncount = 0\na = list(map(int,input().split()))\ntemp = []     # temp 列表用于临时存储每个小朋友在当前轮次要分出去的一半糖果数量\nnew = []      # 为了不让原有的a[0]接收a[1]的一半后改变后对后续a[n-1]的影响，新创建一个列表存储分完糖果后每个小朋友的新糖果数\n\nwhile len(set(a)) != 1:      # 循环条件：使用 while len(set(a)) != 1 来判断所有小朋友的糖果数是否相同，若不同则继续循环。\n    new = []\n    for i in range(n):\n        temp.append(a[i]//2)      # 存储每个小朋友要分出去的一半糖果\n\n    for i in range(n-1):\n        new.append(a[i]//2 + temp[i+1])     # 存储分完糖果后每个小朋友的新糖果数\n    new.append(a[n-1]//2 + temp[0])\n    a = new           # 将 new 列表赋值给 a，更新当前每个小朋友的糖果数。\n\n    temp.clear()         # 清空temp列表供下一次临时存放\n    for i in range(n):    # 检查是否有奇数颗糖的小朋友，有则补发糖果\n        if a[i] % 2 != 0:\n            a[i]+=1\n            count+=1\n\nprint(count)\n\n其实弄懂了之后temp[]列表可以省略掉，进一步优化：\nn = int(input())\ncount = 0\na = list(map(int,input().split()))\nwhile len(set(a)) != 1:\n    new = []\n    for i in range(n-1):\n        new.append(a[i]//2 + a[i+1]//2)\n    new.append(a[n-1]//2 + a[0]//2)\n    a = new\n    for i in range(n):\n        if a[i] % 2 != 0:\n            a[i]+=1\n            count+=1\nprint(count)\n\n E 正文"},{"aid":"108663","title":"编写题解 1431: 蓝桥杯2014年第五届真题-分糖果","date":"2025-03-03","likes":0,"views":647,"md":"S 正文\n原题链接：蓝桥杯2014年第五届真题-分糖果\n\n解题思路:\n\n注意事项:\n\n参考代码:\n#include<stdio.h>\nint main()\n{\n\tint n,num[100]={0}, bu = 0, i, f = 0;\n\tscanf(\"%d\", &n);\n\tfor (i = 0; i < n; i++)\n\t{\n\t\tscanf(\"%d\", &num[i]);\n\t}\n\tint t;\n\twhile (1)\n\t{\n\t\tt = num[0];\n\t\tfor (i = 0; i < n; i++)\n\t\t{\n\t\t\tif (t != num[i])\n\t\t\t\tbreak;\n\t\t}\n\t\tif (i == n)\n\t\t{\n\t\t\tprintf(\"%d\", bu);\n\t\t\treturn 0;\n\t\t}\n\t\tfor (i = 0; i < n; i++)\n\t\t{\n\t\t\tnum[i] = num[i] / 2;\n\t\t\tif (i == 0)\n\t\t\t{\n\t\t\t\tf = num[i];\n\t\t\t}\n\t\t\tif (i == n - 1)\n\t\t\t{\n\t\t\t\tnum[i] = num[i]+f;\n\t\t\t}\n\t\t\telse\n\t\t\t\tnum[i] = num[i] + num[i + 1]/2;\n\t\t\tif (num[i] % 2 != 0)\n\t\t\t{\n\t\t\t\tbu++;\n\t\t\t\tnum[i]++;\n\t\t\t}\n\t\t}\n\t}\n}\n\n E 正文"},{"aid":"108451","title":"纯循环（一下标题太短，一下标题敏感，神经）","date":"2025-02-13","likes":0,"views":619,"md":"S 正文\n原题链接：蓝桥杯2014年第五届真题-分糖果\n\n解题思路:\n\n注意事项:\n\n参考代码:\n#include<bits/stdc++.h>\n#include<string>\nusing namespace std;\nint n;   int a[101]; int temp=0;  int ans=0;\nint flag=0; //设置标志\nint main()\n{\n\tcin>>n;\n\tfor(int i=0;i<n;i++)\n\t{\n\t\tcin>>a[i];\n\t}\nwhile(!flag)\n{\n\tfor(int i=0;i<n;i++)\n\t{\n\t\ta[i]/=2;\n\t}\n\tint temp=a[n-1];  //储存最后一个\n\tfor(int i=n-1;i>0;i--)\n\t{\n\ta[i]+=a[i-1];   //进行交换\n\t}\n\ta[0]+=temp;   //第一个等于最后一个的一半加上自身\n\t//判断\n\tfor(int i=0;i<n;i++)     //判断奇数\n\t{\n\tif(a[i]%2!=0)\n\t{\n\t\ta[i]++;\n\t\tans++;  //计数\n\t}\n\t}\n\tflag=1;   //不要忘记跳出循环\n\tfor(int i=0;i<n-1;i++)\n\t{\n\t\tif(a[i]!=a[i+1])\n\t\t{\n\t\t\tflag=0;      //继续循环\n\t\t}\n\t}\n}\ncout<<ans<<endl;\nreturn 0;\n}\n\n E 正文"},{"aid":"106960","title":"蓝桥杯2014年第五届真题-分糖果，新手只会用循环超强解法！！！","date":"2024-11-07","likes":0,"views":631,"md":"S 正文\n原题链接：蓝桥杯2014年第五届真题-分糖果\n\n解题思路:\n\n注意事项:\n\n参考代码:\n#include\"bits/stdc++.h\"\nusing namespace std;\nint main()\n{\n    int a,b[110]={0},c[110]={0},d[110]={0},v[110]={0},n=0;\n    cin>>a;\n    for(int i=1;i<=a;i++){\n        cin>>b[i];\n    }\n    while(true){\n        int gg=0;\n        for(int i=1;i<=a;i++){//将数组b的值赋给数组d，用于后续判断\n            d[i]=b[i];\n        }\n        for(int i=1;i<=a;i++){//判断数组内的数是否完全相等\n            for(int j=1;j<=a;j++){\n                if(d[i]-d[j]==0){\n                    gg++;\n                }\n            }\n        }\n        if(gg==a*a){//若gg==a*a，则说明数组内所有数相等，可以退出循环\n            break;\n        }\n        for(int i=1;i<=a;i++){//将数组b的值的一半赋给数组c，用于后续计算\n            c[i]=b[i]/2;\n        }\n        for(int i=1;i<=a;i++){//将数组c的值赋给数组v，便于后续计算\n            v[i]=c[i];\n        }\n        for(int i=1;i<=a;i++){//按照题目要求，计算\n            if(i==a){\n                c[a]=c[a]+v[1];\n            }\n            else{\n                c[i]=c[i]+v[i+1];\n            }\n        }\n        for(int i=1;i<=a;i++){//判断数组c的数是否为偶数，不是则+1，n计数器+1及补糖数\n            if(c[i]%2==1){\n                n++;\n                c[i]+=1;\n            }\n        }\n        for(int i=1;i<=a;i++){//将数组c的值赋给数组b，便于下一次循环\n            b[i]=c[i];\n        }\n    }\n    cout<<n<<endl;\n    return 0;\n}\n\n E 正文"}],"1436":[{"aid":"108057","title":"蓝桥杯2014年第五届真题-地宫取宝   记忆化搜索","date":"2024-12-24","likes":0,"views":707,"md":"S 正文\n原题链接：蓝桥杯2014年第五届真题-地宫取宝\n\n解题思路:\n\n注意事项:\n\n参考代码:\n#include\"bits/stdc++.h\"\nusing namespace std;\n#define ll long long\n// 定义全局变量n, m, k分别表示行数、列数和步数限制\nll n, m, k;\n// 定义二维数组a，用于存储输入的矩阵\nll a[60][60];\n// 定义四维数组kkk，用于记忆化搜索，避免重复计算\nll kkk[60][60][15][15];\nll dfs(ll x, ll y, ll z, ll kk) {\n    // 如果当前状态已经计算过，直接返回结果\n    if (kkk[x][y][z][kk] != -1) {\n        return kkk[x][y][z][kk];\n    }\n    // 初始化路径数量为0\n    ll sum = 0;\n    // 如果超出边界或者步数超过限制，返回0\n    if (x > n || y > m || kk > k) {\n        return 0;\n    }\n    // 如果到达终点且步数符合要求，返回1\n    if (x == n && y == m && (kk == k || (kk == k - 1 && a[x][y] > z))) {\n        return 1;\n    }\n    // 如果当前位置的值大于上一个位置的值，取宝贝尝试向下或向右移动\n    if (a[x][y] > z) {\n        sum += dfs(x, y + 1, a[x][y], kk + 1); // 向右移动\n        sum += dfs(x + 1, y, a[x][y], kk + 1); // 向下移动\n    }\n    // 不取宝贝尝试向下或向右移动\n    sum += dfs(x + 1, y, z, kk); // 向下移动\n    sum += dfs(x, y + 1, z, kk); // 向右移动\n\n    // 将计算结果存入记忆化数组中\n    kkk[x][y][z][kk] = sum;\n\n    // 返回结果并取模，防止溢出\n    return sum % 1000000007;\n}\n\nint main() {\n    // 读取输入的行数、列数和步数限制\n    cin >> n >> m >> k;\n    // 初始化记忆化数组为-1，表示未计算过的状态\n    memset(kkk, -1, sizeof(kkk));\n    // 读取矩阵数据\n    for (int i = 1; i <= n; i++) {\n        for (int j = 1; j <= m; j++) {\n            cin >> a[i][j];\n        }\n    }\n    // 输出从起点(1,1)开始满足条件的路径数量\n    cout << dfs(1, 1, -1, 0) << endl;\n    return 0;\n}\n\n E 正文"},{"aid":"104322","title":"C++ 地宫取宝 DP","date":"2024-04-10","likes":0,"views":872,"md":"S 正文\n原题链接：蓝桥杯2014年第五届真题-地宫取宝\n\n解题思路:看了一眼数据这么小想到可以利用DP解决 想出dp表达式idp[i][j][t][c];//坐标为 i j 最大价值为t 身上宝物为c时候的状态数量 分两种情况转移 1.没选当前格子的 2.能够选当前格子的\n\n注意事项:记得开long long\n\n参考代码:\n#include<bits/stdc++.h>\n#define int long long\n#define MO 1000000007\nusing namespace std;\nint dp[55][55][15][15];//坐标为 i j 最大价值为t 身上宝物为c时候的状态数量\nint n,m,k,ma[55][55];\nsigned main()\n{\n    ios::sync_with_stdio(0);cin.tie(0);cout.tie(0);\n    cin>>n>>m>>k;\n    for(int i=1;i<=n;i++){\n        for(int j=1;j<=m;j++){\n            cin>>ma[i][j];\n            ma[i][j];\n            ma[i][j]++;\n        }\n    }\n    dp[1][1][ma[1][1]][1]=dp[1][1][0][0]=1;\n    for(int i=1;i<=n;i++){\n        for(int j=1;j<=m;j++){\n            for(int t=0;t<=12;t++){\n                for(int c=0;c<=k;c++){\n                    //先不选\n                    dp[i][j][t][c]=(dp[i][j][t][c]+dp[i-1][j][t][c]+dp[i][j-1][t][c])%MO;\n                    //如果能选\n                    if((ma[i][j])==t&&c>0){\n                        //记得包括多种情况\n                        for(int temp=0;temp<t;temp++){\n                            dp[i][j][t][c]=(dp[i][j][t][c]+dp[i-1][j][temp][c-1])%MO;\n                            dp[i][j][t][c]=(dp[i][j][t][c]+dp[i][j-1][temp][c-1])%MO;\n                        }\n                    }\n                }\n            }\n        }\n    }\n    int ans=0;\n    for(int i=0;i<15;i++){ans+=dp[n][m][i][k];ans%=MO;}\n    cout<<ans<<endl;\n}\n\n E 正文"},{"aid":"95698","title":"两种代码便于理解学习 普通DFS/DFS+记忆化搜索","date":"2023-04-06","likes":0,"views":890,"md":"S 正文\n原题链接：蓝桥杯2014年第五届真题-地宫取宝\n\n注意：下面有两种代码，第二种是大部分人可以想到的，但是会超时，第一种就是记忆化搜索，\n            放两种代码的目的就是说明普通DFS和记忆化+DFS差的不多，便于大家参考学习。\n参考代码:\n#include<bits/stdc++.h>\nusing namespace std;\ntypedef long long LL;\nint n,m,k;\nint a[51][51];\nLL jy[51][51][13][13];\n\t//记忆化搜索 每个下标的含义与dfs函数一样\nLL dfs(int x,int y,int num,int max){\n\t//不等于-1就说明判断过这种情况，可以直接返回存过的值\n\tif(jy[x][y][num][max+1]!=-1) return jy[x][y][num][max+1];\n\tint lmax=a[x][y];\n\tLL sum=0;\n\tif(x>n || y>m || num>k) return 0;\n\tif(x==n && y==m && (k==num || (num==k-1 && lmax>max)))\n\t\treturn 1;\n\tif(lmax>max){  //拿宝物\n\t\tsum+=dfs(x+1,y,num+1,lmax);\n\t\tsum+=dfs(x,y+1,num+1,lmax);\n\t}\n\t//不拿宝物\n\tsum+=dfs(x+1,y,num,max);\n\tsum+=dfs(x,y+1,num,max);\n\tjy[x][y][num][max+1]=sum;\n\t//将这种情况存下来，加1是因为初始是-1，会越界，所以默认所有情况都加1\n\treturn sum%1000000007;\n\n}\nint main(){\n\tios::sync_with_stdio(false);\n\tcin.tie(0);\n\tcout.tie(0);\n\tmemset(jy,-1,sizeof(jy));\n\tcin >> n >> m >> k;\n\tfor(int i=1;i<=n;i++)\n\t\tfor(int j=1;j<=m;j++)\n\t\t\tcin >> a[i][j];\n\tcout << dfs(1,1,0,-1);\n\treturn 0;\n}\n\n/*\nint a[51][51];\nLL sum=0;\nint n,m,num;\nvoid DFS(int x,int y,int k,int max){\n\tint lmax=a[x][y];\n\tif(x==n && y==m && (k==num || (k==num-1 && lmax>max))){\n\t\tsum++;\n\t\tsum=sum%1000000007;\n\t\treturn;\n\t}\n\tif(x>n || y>m || k>num)\n\t\treturn;\n\tif(lmax>max){  //拿宝物\n\t\tDFS(x+1,y,k+1,lmax);\n\t\tDFS(x,y+1,k+1,lmax);\n\t}\n\t//不拿宝物\n\tDFS(x+1,y,k,max);\n\tDFS(x,y+1,k,max);\n}\nint main(){\n\tios::sync_with_stdio(false);\n\tcin.tie(0);\n\tcout.tie(0);\n\tcin >> n >> m >> num;\n\tfor(int i=1;i<=n;i++)\n\t\tfor(int j=1;j<=m;j++)\n\t\t\tcin >> a[i][j];\n\tDFS(1,1,0,-1);\n\tcout << sum;\n\treturn 0;\n}\n*/\n\n E 正文"},{"aid":"91557","title":"超详细通俗易懂C++","date":"2022-11-16","likes":0,"views":717,"md":"S 正文\n原题链接：蓝桥杯2014年第五届真题-地宫取宝\n\n     解题思路:1.用四维表示小明每次达到一个位置，此时已经拿到的宝贝数目以及最近获得的宝贝价值，最近获得的可以是当前格子取的，也可以是当前格子不取之前宝贝的价值；用四维的原因是，我们不仅要记录小明所在格子位置，还要记录他现在有几个宝贝，这样才能判断到底能否再终点达到恰好k个，还要记录小明现在拿的宝贝最大价值多少，进行价值不同各种方案的相加。也就是k,c表示的值是我们都要一直维护的，所以要用四维。\n        2.在这个代码中，只分为拿和不拿，要是拿，那么只有一种情况->当前格子的宝贝价值一定大于小明现在拥有的宝贝的，这样就排除了当前格子宝贝价值大于小明已有的，纠结是拿是不拿的问题。\n        3.在拿和不拿的情况中都有两种情况，分别是从左边来的和从上面来的，因为小明只能右走和下走，分这种情况是因为我们代码中要用之前格子的方案数目来获得现在格子的方案数目，所以要追溯来路。\n        4.四维 f[i][j][k][c]表示当前（i，j）位置格子小明已经拥有的宝贝数目k,以及最近获得宝贝价值，注意若当前格子获取宝贝，那么c就是当前格子的，若不获取，就是之前的。\n            (1)在(i,j)位置不取，从左边来，之前位置的c就为当前位置的c,上面来的同理\nf[i][j-1][k][c]           （2）在(i,j)位置不取当前格子宝贝，从上面来：\nf[i-1][j][k][c]            (3)在(i,j)位置获取当前格子的宝贝，从左面来，t为之前位置的c,只不过这里t<c,因为要满足取的宝贝价值一定大于之前拥有宝贝的，小于c时t有多种i情况，而不取时只有c一种情况，所以当取时，要把所有t的情况都枚举加起来\n\nf[i][j-1][k-1][t]            (4)在(i,j)位置取宝贝，从上面来：\n\nf[i-1][j][k-1][t]t要多种情况枚举：\n\nif(k>0&&C[i][j]==c){\n                        for(int t=0;t<C[i][j];t++){\n                            f[i][j][k][c]=((f[i][j][k][c]+f[i-1][j][k-1][t])%mod+f[i][j-1][k-1][t])%mod;\n                        }\n                    }        5.给f[i][j][k][c]的起点初始化对应方案数目，其他值默认初值为0，因为(i,j)从（1，1）开始遍历赋值，所以i=0；j=0时边缘化，为0不会影响，其余位置后续会通过循环赋值；\n\n// 取第一个物品\n    f[1][1][1][C[1][1]]=1;\n    // 不取第一个物品\n    f[1][1][0][0]=1;由于起点不取第一个物品时，,因为物品价值范围为[0,12],可以取0值，所以物品价值c应为-1，但是不允许-1索引，所以把输入所有宝贝价值统一加一，用0表示-1。\nfor(int i=1;i<=n;i++){\n        for(int j=1;j<=m;j++){\n            cin>>C[i][j];\n            // 因为价值有0，所以整体加1，用0表示原来起点不取宝贝c为-1这个数值\n            C[i][j]++;\n        }\n    }        6.注意f[i][j][k][c]为不取左,上，取左，上四种情况相加的方案数，在最后求终点恰好k个物品的方案数目res时，为f[n][m][k][i]（其中i包含0-13）这些状态的值相加；\n注意事项：\n1.在取时的判断：k要大于0，因为f[i][j][k][c]中k为当前状态已经获取的宝贝数目，若c为当前格子取的，那么k一定不为0，不然就与之矛盾\nif(k>0&&C[i][j]==c)2.涉及mod，一般最后结果还要取模\n\nres=(res+f[n][m][K][i])%mod;参考代码:\n\n#include<iostream>\n#include <cstdio>\n#include <cmath>\nusing namespace std;\n// 数值随意，满足1<=n,m<=50,1<=k<=12,够用就行\n// 价值数组，存储格子内宝贝的价值\nint C[55][55];\n/* f[i][j][k][c],(i,j)为当前所在格子位置，k为当前位置已经拿到的宝贝数目，c为最近取得的宝贝的价值*/\nint f[55][55][15][15];\nint mod=1000000007;\n\nint n,m,K;\nint main()\n{\n    cin>>n>>m>>K;\n    for(int i=1;i<=n;i++){\n        for(int j=1;j<=m;j++){\n            cin>>C[i][j];\n            // 因为价值有0，所以整体加1，用0表示原来起点不取宝贝c为-1这个数值\n            C[i][j]++;\n        }\n    }\n    // 其余默认初值为0\n    // 取第一个物品\n    f[1][1][1][C[1][1]]=1;\n    // 不取第一个物品\n    f[1][1][0][0]=1;\n    // (i,j)从1开始搜索，因为后续有i-1防止出现-1索引，并且相对于从0索引更直观\n    for(int i=1;i<=n;i++){\n        for(int j=1;j<=m;j++){\n            for(int k=0;k<=K;k++){\n                for(int c=0;c<=13;c++){\n                    // 不取的情况包括从左边和从上面来的,\n                    f[i][j][k][c]=((f[i][j][k][c]+f[i-1][j][k][c])%mod+f[i][j-1][k][c])%mod;\n                    // 取宝贝，要满足k>0且当前位置宝贝价值为c\n                    // 从左边和上面来的情况里，小于c的所有情况都加起来\n                    if(k>0&&C[i][j]==c){\n                        for(int t=0;t<C[i][j];t++){\n                            f[i][j][k][c]=((f[i][j][k][c]+f[i-1][j][k-1][t])%mod+f[i][j-1][k-1][t])%mod;\n                        }\n                    }\n\n                }\n            }\n        }\n    }\n    int res=0;\n    // 把终点位置恰好获得k个宝贝价值从0-13所有情况加起来\n    for(int i=0;i<=13;i++){\n        res=(res+f[n][m][K][i])%mod;\n    }\n    cout<<res;\n    return 0;\n}\n\n E 正文"},{"aid":"91351","title":"标准C语言满分题解！！！","date":"2022-11-09","likes":0,"views":772,"md":"S 正文\n原题链接：蓝桥杯2014年第五届真题-地宫取宝\n\n解题思路:\n\n注意事项:\n\n为什么是四维？\n\n因为里面有坐标i,j从两个方向来，还有k件物品需要维护，另外还有最后一件物品的价值c需要维护，因为需要c来比较，是否取不取，这样就可以表示出，这个问题了。\n\n参考代码:\n#include <stdio.h>\nint dp[51][51][15][15];//dp[i][j][k][v]表示走到坐标为[i,j],取了k个数,最后一个物品的价值是v的方案数\nint c[51][51];  //输入得n*m矩阵\nint main()\n{\n    int i,j,u,l;\n    int n,m,k;\n    scanf(\"%d%d%d\",&n,&m,&k); //输入\n    for(i=1;i<=n;i++)\n    {\n        for(j=1;j<=m;j++)\n        {\n            scanf(\"%d\",&c[i][j]);\n        }\n    }\n    dp[1][1][0][-1]=1; //不取左上角 边界赋值 避免无法取到价值为0的物品 将最后一个参数置为-1\n    dp[1][1][1][c[1][1]]=1;//取左上角\n\n    for(i=1;i<=n;i++) //遍历矩阵\n    {\n        for(j=1;j<=m;j++)\n        {\n            if(i==1&&j==1)\n            {\n                continue;\n            }\n            for(u=0;u<=k;u++) //枚举所有方案数 选了u个物品\n            {\n                for(l=-1;l<=12;l++) //枚举最后一个物品的价值(最大价值)\n                {\n                    //不取(i,j)位置上的物品\n                    int *num=&dp[i][j][u][l];\n                    (*num)=((*num)+dp[i-1][j][u][l])%1000000007; //从上方下来\n                    (*num)=((*num)+dp[i][j-1][u][l])%1000000007; //从左边过来\n\n                    //取(i,j)位置上的物品\n                    if(u>0&&c[i][j]==l)  //枚举取当前[i,j]位置上的物品 当前物品的价值必须等于l\n                    {\n                        for(int w=-1;w<l;w++)  //枚举上一个方案中小于最后一个物品价值的所有可能\n                        {\n                            (*num)=((*num)+dp[i-1][j][u-1][w])%1000000007;\n                            (*num)=((*num)+dp[i][j-1][u-1][w])%1000000007;\n                        }\n                    }\n                }\n            }\n        }\n    }\n    int num=0;\n    for(i=-1;i<=12;i++)\n    {\n        num=(num+dp[n][m][k][i])%1000000007;\n    }\n    printf(\"%d\",num);\n    return 0;\n}\n\n E 正文"}],"1444":[{"aid":"106721","title":"1444: 蓝桥杯2014年第五届真题-斐波那契(python)","date":"2024-10-23","likes":1,"views":673,"md":"S 正文\n原题链接：蓝桥杯2014年第五届真题-斐波那契\n\n Server-side output Markdown text\n![](/image_editor_upload/20241023/20241023082452_46499.jpg)\n### A矩阵分解示例\n![](/image_editor_upload/20241023/20241023082535_93651.png)\n~~~python\ndef mm_yu(x,y,mod):\n    a =[[0,0],[0,0]]\n    for i in range(2):\n        for j in range(2):\n            for k in range(2):\n                a[i][j] += (x[i][k] * y[k][j])%mod\n    return a\n\ndef quick_mm_yu(M,N,mod):\n    E = [[1,0],[0,1]]\n    while N:\n        if N%2 !=0:\n            E = mm_yu(E,M,mod)\n        M = mm_yu(M,M,mod)\n        N >>=1\n    return E\n\ndef fibonacci_yu(M,n,mod):\n    f = [[1,0],[1,0]]\n    return mm_yu(quick_mm_yu(M,n-2,mod),f,mod)[0][0]%mod\n\ndef mm(x,y):\n    a =[[0,0],[0,0]]\n    for i in range(2):\n        for j in range(2):\n            for k in range(2):\n                a[i][j] += x[i][k] * y[k][j]\n    return a\n\ndef quick_mm(M,N):\n    E = [[1,0],[0,1]]\n    while N:\n        if N%2 !=0:\n            E = mm(E,M)\n        M = mm(M,M)\n        N >>=1\n    return E\n\ndef fibonacci(M,n):\n    f = [[1,0],[1,0]]\n    return mm(quick_mm(M,n-2),f)[0][0]\n\nn,m,p = map(int,input().split())\nM = [[1,1],[1,0]]\nif m>n+2 :\n    print(fibonacci_yu(M,n+2,p)%p-1)\nelse:\n    mod = fibonacci(M,m)\n    print(fibonacci_yu(M,n+2,mod)%mod%p-1)\n~~~\n参考：\n[https://blog.dotcpp.com/a/99877](https://blog.dotcpp.com/a/99877)\n[https://blog.csdn.net/flyfish1986/article/details/48014523](https://blog.csdn.net/flyfish1986/article/details/48014523)\n\n E 正文"},{"aid":"99877","title":"蓝桥杯2014年第五届真题-斐波那契（Python题解）","date":"2023-11-16","likes":0,"views":857,"md":"S 正文\n原题链接：蓝桥杯2014年第五届真题-斐波那契\n\n解题思路:\n\n注意事项:\n\n参考代码:\n\nwhile True:\n    try:\n        n,m,p = map(int,input().split())\n        M = [[1,1],[1,0]]\n        def mulMatrix(x, y,mod):  # 定义二阶矩阵相乘的函数\n            ans = [[0 for i in range(2)] for j in range(2)]\n            for i in range(2):\n                for j in range(2):\n                    for k in range(2):\n                        ans[i][j] += (x[i][k] * y[k][j])%mod\n            return ans\n\n        def quickMatrix(M, N,mod):      #矩阵快速幂\n            E = [[1,0],[0,1]]  # 先定义一个单位矩阵\n            while (N):\n                if N % 2 != 0:\n                    E = mulMatrix(E,M,mod)\n                M = mulMatrix(M,M,mod)\n                N >>= 1\n            return E\n\n        def fib(M,q,mod):     #返回第q个斐波那契数\n            s = [[1,1],[0,0]]\n            res = mulMatrix(s,quickMatrix(M,q-2,mod),mod)[0][0]%mod\n            return res\n\n        def mulMatrix_1(x, y):  # 定义二阶矩阵相乘的函数\n            ans = [[0 for i in range(2)] for j in range(2)]\n            for i in range(2):\n                for j in range(2):\n                    for k in range(2):\n                        ans[i][j] += x[i][k] * y[k][j]\n            return ans\n\n        def quickMatrix_1(M, N):      #矩阵快速幂\n            E = [[1,0],[0,1]]  # 先定义一个单位矩阵\n            while (N):\n                if N % 2 != 0:\n                    E = mulMatrix_1(E,M)\n                M = mulMatrix_1(M,M)\n                N >>= 1\n            return E\n\n        def fib_1(M,q):     #返回第q个斐波那契数\n            s = [[1,1],[0,0]]\n            res = mulMatrix_1(s,quickMatrix_1(M,q-2))[0][0]\n            return res\n\n        if m >= n+2:\n            print(fib(M,n+2,p)%p-1)\n        else:\n            mod = fib_1(M,m)\n            print(fib(M,n+2,mod)%fib_1(M,m)%p-1)\n    except:\n        break\n\n E 正文"},{"aid":"96351","title":"蓝桥杯2014年第五届真题-斐波那契(详细解答）","date":"2023-05-07","likes":0,"views":1166,"md":"S 正文\n原题链接：蓝桥杯2014年第五届真题-斐波那契\n\n在解答本题前，我会先介绍一些待会会用到的知识。\n1、取模公式：（a+b）%p=(a%p+b%p)%p;\n                         (a-b）%p=(a%p-b%p)%p;\n                       （a*b）%p=(a%p*b%p)%p;\n     因为C语言的long long最多只能表示19位数，当遇到非常大的数取模时是上面的公式就非常有用。\n2、斐波那契数列矩阵求法：\n\n![](https://blog.dotcpp.com/uploads/20230507/1683457037764406.jpg)\n3、快速幂：\n      求2的1024次幂，用一个for循环可以很快求出，如果是2的10000000000次幂还可以很快就求出接过吗？显然不行。所以，需要用到快速幂的方法。\n      比如：2^1024 = 4^512 = 16^256 = 256^128 = 65536^64……\n      按照这种方法设计一个循环，其循环次数会比原先的循环次数减少非常多\n     （如果读者对快速幂感兴趣可以自行查阅资料，这里只作简单说明）\n4、矩阵快速幂：\n      矩阵快速幂是第二和第三点的结合，通过矩阵的快速幂可以快速地求出第N个斐波那契数。\n\n![](https://blog.dotcpp.com/uploads/20230507/1683459432641004.jpg)\n5、斐波那契数列求和：\n    由F(n)=F(n-1)+F(n-2)可以得到斐波那契数列前n项和 Sn=F(n+2)-1\n\n题目分析：\n    如果这道题的测试数据很小，那这道题就非常简单。但问题就是这道题的测试数据很大。\n    因此我们必须考虑两方面：程序执行时间不能超过限制和运算数据不能超过范围（C语言的long long最多只能表示19位数）。程序执行时间可以通过矩阵快速幂      和位运算来减少。而运算数据可以通过大数相乘取模的方法解决（下面会详细分析）。\n    这道题还要分两种情况讨论：第一种Sn>F(m)，Sn需要先对F(m)取模，在对p取模。这里有个小细节，就是Sn和F(m)都不会太大，可以通过硬算得出，因为Sn要      对F(m)取模，而F(m)如果太大是没有办法通过程序计算得出的，所以不用担心F(m)太大。第二种Sn<F(m)，Sn无需先F(m)取模，在对p取模，因为Sn对F(m)取模      仍为Sn。\n#include <stdio.h>\ntypedef long long ll;    //给long long 定义一个新名字，方便后面使用\nlong long D[2][2],E[2][2];\nvoid power(ll n);    //当SnF(m)时的矩阵快速幂函数\nvoid matrix(ll (*M_1)[2],ll (*M_2)[2]);    //当SnF(m)时的矩阵相乘取余  ll (*M_1)[2]是定义了一个可以存储二维数组的指针\nint main(){\n\tll Sn1=0,Sn2=0,fn=0,n,m,p,y;\n\tscanf(\"%lld %lld %lld\",&n, &m, &p);\n\tif(m>n+2){\n\t\tpower1(n+2,p);\n\t\tSn1=E[0][1]%p;\n\t\ty=Sn1-1;\n\t}else if(m1){\n\t\tif(n&1){    //当n为奇数时 n&1等价于n%2!=0\n\t\t\tmatrix(A,C);    //矩阵A和C相乘\n\t\t\tn--;\n\t\t}\n\t\tmatrix(A,A);    //矩阵A和A相乘\n\t\tn>>=1;    //n>>=1 等价于 n/=2 不过位运算可以提高速度\n\t}\n\tmatrix(A,C);    //矩阵A和C相乘，得出D[0][1]即Sn\nvoid power1(ll n,ll p){\n\tll A1[2][2]={{1,1},{1,0}},C1[2][2]={{1,0},{0,1}};\n\twhile(n>1){\n\t\tif(n&1){\n\t\t\tmatrix1(A1,C1,p);    //矩阵A1和C1相乘,并对p取余，不然数组内的元素大小会呈现指数型增长，超过范围\n\t\t\tn--;\n\t\t}\n\t\tmatrix1(A1,A1,p);    //矩阵A1和A1相乘,并对p取余\n\t\tn>>=1;\n\t}\n\tmatrix1(A1,C1,p);    //矩阵A1和C1相乘,并对p取余，得出E[0][1]\n\n}\nvoid matrix(ll (*M_1)[2],ll (*M_2)[2]){    //模拟矩阵M_1和矩阵M_2相乘\n\tint i,j,k,num=0;\n\tll a[8];\n\tfor(i=0;i<2;i++){\n\t\tfor(j=0;j<2;j++){\n\t\t\tfor(k=0;k<2;k++){\n\t\t\t\ta[num]=M_1[i][j]*M_2[j][k];\n\t\t\t\tnum++;\n\t\t\t}\n\t\t}\n\t}\n\tk=0;\n\tfor(i=0;i<2;i++){\n\t    for(j=0;j<2;j++){\n\t\t\tD[i][j]=M_2[i][j]=a[k]+a[k+2];\n\t\t\tk++;\n\t\t}\n\t\tk+=2;\n\t}\n}\nvoid matrix1(ll (*M_3)[2],ll (*M_4)[2],ll p){\n\tint i,j,k,num=0;\n\tll a[8];\n\tfor(i=0;i<2;i++){\n\t\tfor(j=0;j<2;j++){\n\t\t\tfor(k=0;k<2;k++){\n\t\t\t\ta[num]=POW(M_3[i][j],M_4[j][k],p);    //矩阵中大数相乘取余\n\t\t\t\tnum++;\n\t\t\t}\n\t\t}\n\t}\n\tk=0;\n\tfor(i=0;i<2;i++){\n\t    for(j=0;j<2;j++){\n\t    \tE[i][j]=M_4[i][j]=(a[k]%p+a[k+2]%p);\n\t\t\tM_4[i][j]=(a[k]%p+a[k+2]%p)%p;    //（a+b）%p=(a%p+b%p)%p;\n\t\t    k++;\n\t\t}\n\t\tk+=2;\n\t}\n}\nll POW(ll a,ll b,ll p)    //假设a=456783456789098765 b=231248956706543678 p=612395485768394503\n{                                 //a,b,p都为18位数，a*b%p根本无法计算。这时可以将a*2%p,b/2,其等价于a*b%p\n    ll sum=0;                //如果一次不够就俩次，两次不过就三次，一直持续下去，直到b<=0.由此，可以得到左侧的函数\n    while(b)                  //你肯定回想b是奇数怎么办，你可以看看if语句，它就是为了解决这个问题的。\n    {\n        if(b&1)\n        {\n            sum=sum+a;\n            sum=sum%p;\n        }\n    a=a<<1;\n        a=a%p;\n        b=b>>1;;\n    }\n    return sum;\n}\n///////////////////////////////////////////////////////////////////////////////////////////////////////////////////////////////////////////////\n///////////////////////////////////////////////////////////////////////////////////////////////////////////////////////////////////////////////\n///上面的代码再复制的过程出现了一些问题////////////下面是没问题的//////////////////////////////////////////////////////////////////////////////\n#include <stdio.h>\ntypedef long long ll;\nlong long D[2][2],E[2][2];\nvoid power(ll n);\nvoid power1(ll n,ll p);\nvoid matrix(ll (*M_1)[2],ll (*M_2)[2]);\nll POW(ll a,ll b,ll p);\nvoid matrix1(ll (*M_3)[2],ll (*M_4)[2],ll p);\nint main(){\n\tll Sn1=0,Sn2=0,fn=0,n,m,p,y;\n\tscanf(\"%lld %lld %lld\",&n, &m, &p);\n\tif(m>n+2){\n\t\tpower1(n+2,p);\n\t\tSn1=E[0][1]%p;\n\t\ty=Sn1-1;\n\t}else if(m<n+2){\n\t\tpower(n+2);\n\t\tSn2=D[0][1]-1;\n\t\tpower(m);\n\t\tfn=D[0][1];\n\t\ty=(Sn2%fn)%p;\n\t}\n\tprintf(\"%lld\",y);\n}\nvoid power(\n\n（正文过长，已截断，全文见原文链接）"},{"aid":"94922","title":"矩阵快速幂-python（最后一个运行超时）","date":"2023-03-16","likes":0,"views":880,"md":"S 正文\n原题链接：蓝桥杯2014年第五届真题-斐波那契\n\n解题思路:\n\n注意事项:\n\n参考代码:\nn,m,p = map(int,input().split())\n\n# 定义快速幂,k为取模的时候使用\ndef fp(base, power:int, k=float('inf')):\n    res = 1\n    while power>0:\n        if power&1:\n            res *= base%k\n        power >>= 1\n        base *= base%k\n    return res\n\n# 矩阵点乘\ndef matrix_m(n,m):\n    R = [[0]*len(m[0]) for i in range(len(n))]\n    for a in range(len(n)):\n        for b in range(len(m[0])):\n            total = 0\n            for c in range(len(n[0])):\n                total += n[a][c]*m[c][b]\n            R[a][b] = total\n    return R\n\n# 矩阵快速幂\ndef m_fp(base,power):\n    def get(n,i):\n        v = [0]*n\n        v[i] = 1\n        return v\n\n    res = [get(len(base),i) for i in range(len(base))]\n    while power>0:\n        if power&1:\n            res = matrix_m(res,base)\n        power >>= 1\n        base = matrix_m(base,base)\n    return res\n\nT = [[1,1],[1,0]]\nf_m = matrix_m(m_fp(T,m-2),[[1],[1]])[0][0]\ns_n = matrix_m(m_fp(T,n),[[1],[1]])[0][0]-1\n\n#print(f_m,s_n)\nprint(s_n%f_m%p)\n\n E 正文"},{"aid":"93476","title":"1444: 蓝桥杯2014年第五届真题-斐波那契","date":"2023-01-19","likes":1,"views":813,"md":"S 正文\n原题链接：蓝桥杯2014年第五届真题-斐波那契\n\n Server-side output Markdown text\n```cpp\n#include<iostream>\n#include<cstring>\nusing namespace std;\ntypedef long long LL;\nLL llmul(LL a,LL b,LL mod)\n{\n    a%=mod;\n    a+=mod;\n    a%=mod;\n    b%=mod;\n    b+=mod;\n    b%=mod;\n    if(a<b)\n        swap(a,b);\n    LL ret=0;\n    while(b)\n    {\n        if(b&1)\n            ret=(ret+a)%mod;\n        a=(a<<1)%mod;\n        b/=2;\n    }\n    return ret;\n}\nstruct matrix\n{\n    LL x[3][3];\n    matrix()\n    {\n        memset(x,0,sizeof(x));\n        return;\n    }\n};\nmatrix mmul(matrix &A,matrix &B,LL mod)\n{\n    matrix ret;\n    for(int i=1;i<=2;i++)\n        for(int j=1;j<=2;j++)\n            for(int k=1;k<=2;k++)\n                ret.x[i][j]=(ret.x[i][j]+llmul(A.x[i][k],B.x[k][j],mod))%mod;\n    return ret;\n}\nmatrix E,A;\nLL fib(LL n,LL mod)\n{\n    matrix O=E,B=A;\n    while(n)\n    {\n        if(n&1)\n            O=mmul(O,B,mod);\n        B=mmul( B,B,mod );\n        n/=2;\n    }\n    return O.x[1][2];\n}\nLL solve(LL n,LL m,LL mod)\n{\n    LL t=n/m,p=t/2,q=t%2,fuhao=p*m%2==0?1:-1;\n    if(q==0)\n    {\n        LL ans=fib(n%m,mod)*fuhao;\n        ans%=mod;\n        ans+=mod;\n        return ans%mod;\n    }\n    if(n%m==0)\n        return 0;\n    LL x=(llmul(fib(n%m,mod),fib(m-1,mod),mod)*fuhao%mod+mod)%mod,y=fib(m,mod),a=fib(n%m-1,mod);\n    if(n%m%2==0)\n        a--;\n    if(fuhao<0)\n        a++;\n    a=(a%mod+mod)%mod;\n    return((x-llmul(a,y,mod))%mod+mod)%mod;\n}\nint main()\n{\n    A.x[1][2]=A.x[2][1]=A.x[2][2]=1;\n    E.x[1][1]=E.x[2][2]=1;\n    LL n,m,mod;\n    cin>>n>>m>>mod;\n    cout<<(solve(n+2,m,mod)-1+mod)%mod;\n    return 0;\n}\n```\n\n E 正文"}],"1449":[{"aid":"94928","title":"dp-波动数列","date":"2023-03-16","likes":1,"views":993,"md":"S 正文\n原题链接：蓝桥杯2014年第五届真题-波动数列\n\n按照大佬的思路 (网址：CSDN)，使用了动态规划解题。\n//  (59条消息) 题目 1449: 蓝桥杯2014年第五届真题-波动数列_一只干饭猿的博客-CSDN博客\n参考代码:\nimport java.util.Scanner;\npublic class Main{\n    static int MOD=100000007;\n    static long num = 0;\n    static long []dp=new long[500001];//numa可能的最大个数\n    public static void main(String[] args) {\n        Scanner scanner = new Scanner(System.in);\n        int n = scanner.nextInt();\n        int s = scanner.nextInt();\n        int a = scanner.nextInt();\n        int b = scanner.nextInt();\n        long  t = (long) n *(n-1)/2;//numa+numb = n*(n-1)/2\n        create(n);\n        for(long i=t;i>=0;i--) //i代表numa\n        {\n           long j = t-i;\n           long  temp = s-i*a+j*b;\n            if (temp%n==0) //x=(s-numa*a+numb*b)/n，x是整数\n            {//+a的位置定下了，-b一定确定了\n                num = num+(dp[Math.toIntExact(i)]%MOD);//不损失精度的把long转换成int\n                num%=MOD;\n            }\n        }\n       System.out.println(num);\n    }\n      public static  void create(int n){\n            int i,j;\n            dp[0] = 1;\n            for (i=1;i<n;i++)//位数\n                for (j=(i*(i+1)/2);j>=i;j--)//滚动数组，从后到前更新j>=i的部分\n                    dp[j] = (dp[j-i]+dp[j])%MOD;//表示当numa=i的时候，n位数列+a的组合数目\n        }\n    }\n\n E 正文"},{"aid":"94699","title":"LikeWater - 1449: 蓝桥杯2014年第五届真题-波动数列C++（动态规划求解）","date":"2023-03-09","likes":0,"views":1333,"md":"S 正文\n原题链接：蓝桥杯2014年第五届真题-波动数列\n\n Server-side output Markdown text\n####解题思路\n1、根据题意，直接反应是利用DFS，但数据量太大，不允许，转而使用动态规划。\n\n2、按照大佬的思路 (网址：[CSDN](https://blog.csdn.net/Haha_Sugar/article/details/123651777 \"CSDN\"))，使用了动态规划解题。大致思路如下：\n\n3、将相邻两项之间的操作看作是一个封装P，P中含有两个操作，即\n`P(+a,-b)`\n因此，可以将前n项之和为s的数列写作满足方程：\n`x+(x+P)+(x+P+P)+...+(x+(n-1)P) = s`\n合并同类项后可以写作\n`nx+(P+2P+3P+...+(n-1)P) = s`\n利用等差数列对P前面的系数求和得到\n`nx+n(n-1)P/2 = s；`\n由于P是封装，它实际是由**numa个+a、numb个-b**组合而成的，因此，上式又可以变更为\n`nx+numa*a-numb*b = s` 且 `numa+numb = n*(n-1)/2；`\n对**numa**进行枚举，当**numa**确定时，**numb**即确定，随即可根据上式求出x的值（即某个符合要求的序列的第一个元素的值）；\n4、当x确定，+a和-b操作的排序不同会产生多种不同的种类数，因此接下来需要对排列可能的数目进行求解，这里就需要用到动态规划了。\n首先，在二维数组中分析dp[i][j]，i代表第i位数字，j代表**numa**的数目，dp[i][j]存储的值代表如果有i位数字，那么j个+a的组合数目，可以得到状态转移方程：\n![](/image_editor_upload/20230309/20230309093746_37880.jpg)\n\n***（对状态转移方程的解释：每当增加了第i位数，如果它由前一个数+a得到，那么对i位数组成的数列而言，所消耗+a将会多出i个，因此有dp[i-1][j-i]这一项；如果它与前一个数之间的关系不是+a，那么有dp[i-1][j]）***\n但是，如果只是用二维的动态转移矩阵求解dp[n][numa]时，发现numa的上限等于n×(n-1)/2，该题n可以多达1000，dp大小可以到（1001×499501），显然，内存会超限；因此，需要使用滚动数组代替二维的转移矩阵。滚动数组赋予i=1初值后，从右到左更新，动态转移方程可以写为：\n   ** d p [ j ] = d p [ j − i ] + d p [ j ]**\n根据以上分析，解题思路是，首先生成一个dp[n*(n-1)/2+1]的矩阵，存储“当位数为n时，不同的numa个数对应的组合数目”；之后枚举**numa**，取符合要求的**numa**（使得x算出来是整数）所对应的dp中的组合数目计入num，最后输出num（注意即时取余数）。\n\n```c\n#include<stdio.h>\n#define MOD 100000007\nint dp[500001];//numa可能的最大个数\n\nvoid create(int n){\n    int i,j;\n    dp[0] = 1;\n    for (i=1;i<n;i++)//位数\n        for (j=(i*(i+1)/2);j>=i;j--)//滚动数组，从后到前更新j>=i的部分\n            dp[j] = (dp[j-i]+dp[j])%MOD;//表示当numa=i的时候，n位数列+a的组合数目\n}\n\nint main()\n{\n\tlong int n,s,a,b,i,j,temp,x,num=0;\n\tscanf(\"%ld %ld %ld %ld\",&n,&s,&a,&b);\n\tlong int t = n*(n-1)/2;//numa+numb = n*(n-1)/2\n\tcreate(n);\n\tfor (i=t;i>=0;i--) //i代表numa\n\t{\n\t    j = t-i;\n\t    temp = s-i*a+j*b;\n\t    if (temp%n==0) //x=(s-numa*a+numb*b)/n，x是整数\n\t    {\n\t        num+=(dp[i]%MOD);//+a的位置定下了，-b一定确定了\n\t        num%=MOD;\n\t    }\n\t}\n\tprintf(\"%ld\",num);\n\treturn 0;\n}\n\n```\n###以上转载自 CSDN:一只干饭猿 ，写的很好，分享给大家！\n\n E 正文"},{"aid":"93666","title":"1449: 蓝桥杯2014年第五届真题-波动数列","date":"2023-02-01","likes":0,"views":964,"md":"S 正文\n原题链接：蓝桥杯2014年第五届真题-波动数列\n\n Server-side output Markdown text\n```cpp\n#include<iostream>\nusing namespace std;\nint n,s,a,b,f[1001][1001];\nint get_mod(int a ,int b)\n{\n    return (a%b+b)%b;\n}\nint main()\n{\n    cin>>n>>s>>a>>b;\n    f[0][0]=1;\n    for(int i=1;i<n;i++)\n        for(int j=0;j<n;j++)\n            f[i][j]=(f[i-1][get_mod(j-i*a,n)]+f[i-1][get_mod(j+i*b,n)])%100000007;\n    cout<<f[n-1][get_mod(s,n)]<<endl;\n    return 0;\n}\n```\n\n E 正文"},{"aid":"85337","title":"C++代码（代码简洁）","date":"2022-03-16","likes":0,"views":1952,"md":"S 正文\n原题链接：蓝桥杯2014年第五届真题-波动数列\n\n Server-side output Markdown text\n\n###解法\n------------\n#####S = x + (x + d1) + (x + d1 + d2) + (x + d1 + d2 + d3) +....\n所以：\nS = nx +(n-1)d1 + (n-2)d2 + (n-3)d3 + .... + dn-1\n\n因为d1 ,d2 , d3 ... dn-1 只是变量， 将其含义交换，就是让dn-1叫d1 , dn-2 叫d2 以此类推\n所以：\n##### S = nx + d1 + 2d2 + 3d3 +.... + (n-1)dn-1\n##### x = ( S - (d1 + 2d2 + ...)) / n\n##### 因为x是整数 ， 所以  S % n == (d1 + 2d2 + ... ) % n\n\n------------\n\n我们可以定义一个数组f[i][j]\ni :  （d1 + 2d2 + 3d3 +.... + (n-1)dn-1）  的前i项\nj :   余数为j\nf[i][j]:前i项中，余数为j的一共有f[i][j]个\n\n而f[i][j] 可以通过前一项推导出来\n##### 第i项就是由第i-1项 + a 或者是 -b 得来的\n令前i-1项和为C ， 则 前i项和为 C + i * a 或 C -i * b\n而 ( C + i * a) % n = j;\n所以 C % n == (j - i*a) % n ;\n所以，前 i - 1 项的和的余数是 (j - i * a ) % n;\n另一种情况就是 (j + i*b) % n;\n\n#####f[0][0] = 0 一项都不选的时候，总和是0，模n的余数显然是0\n\n###对于取模，可能会模出负数，但是数组下标没有负数\n所以，应避免出现负数情况\na % b 改成  (a % b + b) % b 这样结果就一定是正数了\n\n------------\n\n```\n#include<iostream>\nusing namespace std;\n\nconst int N = 1005;\nint n , s , a , b ;\nint f[N][N];\nint MOD = 100000007;\n\nint get_mod(int a , int b){\n    return (a % b + b) % b;\n}\n\nint main(){\n    cin >> n >> s >> a >> b;\n    f[0][0] = 1;\n    for(int i = 1 ; i < n ; i++)\n        for(int j = 0 ; j < n ; j++)\n            f[i][j] = ( f[i-1][get_mod(j - i * a , n)] + f[i-1][get_mod(j + i * b , n)] ) % MOD;\n    cout << f[n-1][get_mod(s , n)] << endl;\n    return 0;\n}\n```\n\n E 正文"},{"aid":"66839","title":"蓝桥杯2014年第五届真题-波动数列-动态规划(C++代码)","date":"2020-02-23","likes":0,"views":2068,"md":"S 正文\n原题链接：蓝桥杯2014年第五届真题-波动数列\n\n Server-side output Markdown text\n# 解决思路：动态规划\n假设第一个数为X， Y = -a 或者 b（注意符号是相反的），对数列所有数求和可以得到：s=nX-Y-2Y-...-(n-1)Y，由于X并没有限制，因此只需要n|s+Y+2Y-...+(n-1)Y。\n设dp[i][j]为满足(s+Y+2Y+...+iY)%n==j的数列个数。初始化dp[0][s] = 1，递推公式：dp[i][j] = dp[i-1][j+a*i] + dp[i-1][j-b*i]（分别对应iY项中Y取-a和Y取b的情况）\n\n```cpp\n#include <bits/stdc++.h>\nusing namespace std;\n#define MOD 100000007\n#define MAX 1005\nlong long dp[MAX][MAX];\nint main()\n{\n\tint n, i, j;\n\tlong long s, a, b, num, sum = 0;\n\tcin>>n>>s>>a>>b;\n\tdp[0][(s%n+n)%n] = 1;\n\tfor (i = 1;i < n;i++)\n\t{\n\t\tfor (j = 0;j < n;j++)\n\t\t{\n\t\t\tdp[i][j] = (dp[i-1][(j+(a*i)%n)%n] + dp[i-1][((j-b*i)%n+n)%n]) % MOD;\n\t\t}\n\t}\n\tcout<<dp[n-1][0]<<endl;\n\treturn 0;\n}\n```\n\n E 正文"}],"1450":[{"aid":"101821","title":"1450: 蓝桥杯2014年第五届真题-矩阵翻硬币","date":"2024-01-13","likes":0,"views":716,"md":"S 正文\n原题链接：蓝桥杯2014年第五届真题-矩阵翻硬币\n\n Server-side output Markdown text\n#\n```cpp\n/*\n * 题目 1450: 蓝桥杯2014年第五届真题-矩阵翻硬币\n * 10^1000 -> 大整数（vector、string待定）\n * flip问题 - 重要的数学关系 - 状态是二维的 - 仅奇数操作改变\n * 题目操作一个格点可以连带修改其整数倍格点。因此，一个点（n,m）的翻动次数是num(n)*num(m),num(int)表示int的约数个数（含自身）\n * 考虑到结果上都是正，也就是原始状态反面的需要翻转奇数次，根据翻转表达式发现尽可能是 奇数*奇数。\n * 小知识点：在包含自身的情况下，仅有完全平方数是奇数。证明：如果不是完全平方数，根据表达式：a = n/b,即{a，b}成对出现且a!=b。\n * 换句话说，只有点（完全平方数，完全平方数）原始状态是反面。\n * 问题转换为在大小为n*m的格网上有几个这样的点考虑到可以使用乘法原理，x轴完全平方数个数*y轴完全平方数个数 = 答案。\n * 于是再次转化问题，考虑数int中有几个完全平方数。这个答案是[sqrt(int)], []表示向下取整。\n * 证明：y=x^2 < int ==> x < sqrt(int)，那么最大的完全平方数是[sqrt(int)]。\n * 接下来就是大整数开方问题：\n * 1.二分可以 - 问题需要先构造大整数（搜索范围） + 设计整除\n * 2.牛顿迭代法 - 利用 x_{n + 1} = 1/2*(x_{n} + a/(x_{n})) - 除法不好设计 比1还难\n * 3.利用关系，开方位数 偶 = len // 2, 奇 = len // 2 + 1; 然后从高至低确认位数 -- 检测\n * 在三种方法中求解 - 牛顿法难度最高，检测中3的利用关系最为简单，并且3会更快。\n * 选用三作为开放算法\n *\n * 方便输入输出 - string。\n */\n#include<cstdio>\n#include<cstring>\n#include<iostream>\n#include<algorithm>\nusing std::cin;\nusing std::cout;\nusing BigInt = std::string;\n\nBigInt mul(BigInt n1, BigInt n2) {\n  BigInt ans;\n  int num[500] = { 0 }, i, j;\n  for (i = 0; i < n1.length(); i++)\n    for (j = 0; j < n2.length(); j++)\n      num[i + j + 1] += (n1[i] - '0') * (n2[j] - '0'); // 答案位置要偏移 -- 最高位需要进位\n\n  // 进位 + 类型转换\n  for (i = n1.length() + n2.length() - 1; i > 0; i--) if (num[i] >= 10)\n  {\n    num[i - 1] += num[i] / 10;\n    num[i] %= 10;\n  }\n  for (int i = 0; i <= n1.length() + n2.length() - 1; i++) if (!i && num[i] || i)\n    ans.push_back(num[i] + '0');\n\n  return ans;\n}\n\nbool BigIntCmpLess(const BigInt& n1, const BigInt& n2, int fill) {\n  if (n1.length() + fill != n2.length()) return n1.length() + fill < n2.length(); // 位数不同，比位数\n  else return n1 < n2; // 相同，扫描比较 -- 选用string的原因 -- 自带了\n}\n\nBigInt num(const BigInt& number) {\n  int len = number.length() / 2;\n  if (number.length() % 2) ++len;       // 确定位数\n\n  // 开始计算\n  BigInt ans;\n  for (int i = 0; i < len; ++i) {\n\tans.push_back('0');\n    for (; BigIntCmpLess(mul(ans, ans), number, 2 * (len - i - 1)); ++ans[i]);\n\t--ans[i]; // 检查出来的是最小的大于，-1还原\n  }\n\n  return ans;\n}\n\nint main() {\n  BigInt n, m;\n  cin >> n >> m;\n  cout << mul(num(n), num(m));\n  return 0;\n}\n```\n\n E 正文"},{"aid":"94286","title":"1450: 蓝桥杯2014年第五届真题-矩阵翻硬币","date":"2023-02-25","likes":0,"views":737,"md":"S 正文\n原题链接：蓝桥杯2014年第五届真题-矩阵翻硬币\n\n Server-side output Markdown text\n```cpp\n#include<iostream>\n#include<algorithm>\nusing namespace std;\nstring StrMul(string s1,string s2)\n{\n    string ans;\n    int num[500]={0},i,j;\n    for(i=0;i<s1.length();i++)\n        for(j=0;j<s2.length();j++)\n            num[i+j+1]+=(s1[i]-'0')*(s2[j]-'0');\n    for(i=s1.length()+s2.length()-1;i>0;i--)\n        if(num[i]>=10)\n        {\n            num[i-1]+=num[i]/10;\n            num[i]%=10;\n        }\n    for(int i=0;i<=s1.length()+s2.length()-1;i++)\n        if(!i&#[i]||i)\n            ans.push_back(num[i]+'0');\n    return ans;\n}\nbool StrCmp(string s1,string s2,int pos)\n{\n    if(s1.length()+pos!=s2.length())\n        return s1.length()+pos>s2.length();\n    else\n        return s1>s2;\n}\nstring SqrtStr(string s)\n{\n    int len;\n    string ans;\n    if(s.length()%2==0)\n        len=s.length()/2;\n    else\n        len=s.length()/2+1;\n    for(int i=0;i<len;i++)\n    {\n        ans.push_back('0');\n        for(int j=0;j<=9;j++)\n        {\n            if(StrCmp(StrMul(ans,ans),s,2*(len-1-i)))\n                break;\n            ans[i]++;\n        }\n        ans[i]--;\n    }\n    return ans;\n}\nint main()\n{\n    string s1,s2;\n    cin>>s1>>s2;\n    cout<<StrMul(SqrtStr(s1),SqrtStr(s2));\n    return 0;\n}\n```\n\n E 正文"},{"aid":"89527","title":"压位高精，使用朴素的二分法来求平方根。","date":"2022-08-20","likes":0,"views":913,"md":"S 正文\n原题链接：蓝桥杯2014年第五届真题-矩阵翻硬币\n\n解题思路:本质就是求sqrt(n)*sqrt(m)，时间复杂度是O（maxlen^3),maxlen是数的位数。使用普通高精显然超时，那就压8位为1位，大大减小系数。\n                开long long防越界（一般压位超过4位就要开long long)\n\n注意事项:\n\n参考代码:\n#include<bits/stdc++.h>//这题转化为对m开根号(向下取整)*对n开根号(向下取整)\n//所以这一题考的就是高精度开根号，高精度乘法\nusing namespace std;\ntypedef long long ll;\n#define maxlen 130\nchar str[1010];\nll n[maxlen],m[maxlen],l[maxlen],r[maxlen],mid1[maxlen],mid2[maxlen],tmp1[maxlen],ans[maxlen];\nint cmp(ll *a,ll *b){//a<b返回-1，a=b返回0，a>b返回1\n    for(int i=maxlen-1;i>=0;i--){\n        if(a[i]<b[i])return -1;\n        if(a[i]>b[i])return 1;\n    }\n    return 0;\n}\nvoid add1(ll *a,int x){//高精度数加一个普通整数，a=a+x\n    a[0]+=x;\n    int i=0;\n    while(a[i]>99999999){\n        a[i+1]+=a[i]/100000000;\n        a[i]%=100000000;\n        i++;\n    }\n}\nvoid add2(ll *a,ll *b,ll *c){//c=a+b+1,这里加1是为了实现l+r+1\n    for(int i=0;i<maxlen;i++){\n        c[i]=a[i]+b[i];\n    }\n    c[0]+=1;\n    for(int i=0;i<maxlen-1;i++){\n        c[i+1]+=c[i]/100000000;\n        c[i]%=100000000;\n    }\n}\nvoid sub(ll *a,int x){//高精度数减一个普通整数，a=a-x\n    a[0]-=1;\n    int i=0;\n    while(a[i]<0){\n        a[i]+=100000000;\n        a[i+1]-=1;\n        i++;\n    }\n}\nvoid divtwo(ll *a){//a=a/2,向下取整\n    for(int i=maxlen-1;i>=1;i--){\n        if(a[i]&1){//如果a[i]是奇数\n            a[i]>>=1;\n            a[i-1]+=100000000;\n        }\n        else{\n            a[i]>>=1;\n        }\n    }\n    a[0]>>=1;\n}\nvoid mul(ll *a,ll *b,ll *c){//c=a*b\n    memset(c,0,1640);//sizeof(long long int)*205\n    for(int i=0;i<maxlen;i++){\n        for(int j=0;j<maxlen;j++){\n            if(i+j+1>maxlen-1)break;\n            c[i+j]+=a[i]*b[j];\n            c[i+j+1]+=c[i+j]/100000000;\n            c[i+j]%=100000000;\n        }\n    }\n}\nvoid copy(ll *a,ll *b){//a=b\n    for(int i=0;i<maxlen;i++){\n        a[i]=b[i];\n    }\n}\nvoid bigsqrt(ll *a,ll *mid){//对a开根号,mid=根号a\n    int cmpans;//mid*mid与a比较的结果\n    while(cmp(l,r)!=0){//当l<r时\n        add2(l,r,mid);\n        divtwo(mid);//l<mid<=r\n        mul(mid,mid,tmp1);\n        cmpans=cmp(tmp1,a);\n        if(cmpans==0)return;\n        else if(cmpans==-1){\n            copy(l,mid);//l=mid\n        }\n        else{\n            copy(r,mid);\n            sub(r,1);//r=mid-1\n        }\n    }\n    copy(mid,l);\n}\nvoid print(ll *aa){//输出\n    bool flag=0;//记录是否能输出\n    for(int i=maxlen-1;i>=0;i--){\n        if(!flag){//如果不能\n            if(aa[i]){\n                flag=1;//找到第一个不是0的位，可以输出了\n                printf(\"%lld\",aa[i]);//第一个不能前补0\n                continue;\n            }\n        }\n        else printf(\"%08lld\",aa[i]);//输出，不用空格或换行\n    }\n}\nint main(){\n    scanf(\"%s\",str);\n    int lenstr=strlen(str);\n    for(int i=0;i<lenstr;i++){//每8位数字作为高精度的一位，这样高精度数组最大长度就是125了\n        n[(lenstr-1-i)/8]*=10;\n        n[(lenstr-1-i)/8]+=str[i]-'0';\n    }\n    scanf(\"%s\",str);\n    lenstr=strlen(str);\n    for(int i=0;i<lenstr;i++){\n        m[(lenstr-1-i)/8]*=10;\n        m[(lenstr-1-i)/8]+=str[i]-'0';\n    }\n    copy(r,n);\n    bigsqrt(n,mid1);\n    copy(r,m);memset(l,0,sizeof(l));\n    bigsqrt(m,mid2);\n    mul(mid1,mid2,ans);\n    print(ans);\n    system(\"pause\");\n    return 0;\n}\n\n E 正文"},{"aid":"85996","title":"看见很多都直接在网上粘贴可能大家不明白其中的意思，我来解释一下","date":"2022-03-30","likes":0,"views":848,"md":"S 正文\n原题链接：蓝桥杯2014年第五届真题-矩阵翻硬币\n\n解题思路:\n首先需要求出最开始有多少枚硬币是反面朝上的。\n那就模拟一下\n\n//第x行第y列被翻动的总次数?\n\n//考虑第1行，第y列， y有多少真因子，就会被翻动多少次，而所有的y中，只有平方数的真因子个数为奇数(约数总是成对出现的)\n\n//考虑第1列，第x行， x有多少真因子，就会被翻动多少次，而所有的x中，只有平方数的真因子个数为奇数\n\n//x, y硬币被翻动的次数=x真因子个数*y真因子个数，只有奇数*奇数=奇数，所以，若要x,y为反面，必须x, y都是平方数\n\n//因此，反面硬币总数= =m中的平方数的个数*n中平方数的个数\n\n//那么在m中有多少个平方数呢?答案是sqrt(m)向下取整个，如9内有三个平方数1, 4, 9; 16里面有4个平方数1, 4, 9, 16; 25内有5个平方数\n\n//因此这个题等价于求sqrt(m)*sqrt(n)，那么怎么对一一个很大的数开平方呢?\n\n//假设一个数的长度为length,其平方根的长度为length/2 (偶数) 或者length/2+1(奇数)，不明白可以看这个图\n\n![](https://blog.dotcpp.com/uploads/20220330/1648641501739236.png)\n//最后我们可以从高位不停地试探，每一个取平方后恰好不超过目标平方数的值\n注意事项:\n\n参考代码:\nimport java.math.BigInteger;\nimport java.util.Arrays;\nimport java.util.Scanner;\n\npublic class T1450矩阵翻硬币 {\n\n    public static void main(String[] args) {\n        Scanner sc = new Scanner(System.in);\n        String s1 = sc.next();\n        String s2 = sc.next();\n        System.out.println(sqrt(s1).multiply(sqrt(s2)));\n\t}\n\n\tprivate static BigInteger sqrt(String s) {\n\t\tint leng = s.length();\n\t\tint len = 0;\n\t\tif (leng%2==0) {\n\t\t\tlen=leng/2;\n\t\t}else {\n\t\t\tlen=leng/2+1;\n\t\t}\n\t\tchar sArr[]=new char[len];\n\t\tArrays.fill(sArr, '0');\n\t\tBigInteger target = new BigInteger(s);\n\t\tfor (int pos = 0; pos < len; pos++) {\n\t\t\tfor (char c = '1'; c <= '9'; c++) {\n\t\t\t\tsArr[pos]=c;\n\t\t\t\tBigInteger pow =new BigInteger(String.valueOf(sArr)).pow(2);\n\t\t\t\tif (pow.compareTo(target)==1) {\n\t\t\t\t\tsArr[pos]-=1;\n\t\t\t\t\tbreak;\n\t\t\t\t}\n\t\t\t}\n\t\t}\n\t\treturn new BigInteger(String.valueOf(sArr));\n\t}\n}\n\n E 正文"},{"aid":"85690","title":"1450: 蓝桥杯2014年第五届真题-矩阵翻硬币 (java, 简单搬运)","date":"2022-03-24","likes":0,"views":799,"md":"S 正文\n原题链接：蓝桥杯2014年第五届真题-矩阵翻硬币\n\n Server-side output Markdown text\n - 题目链接: https://www.dotcpp.com/oj/problem1450.html\n - 思路啥的直接参考原地址吧:https://blog.dotcpp.com/a/69012\n 这里就是简单地把这位大佬的代码用java实现了一下, 仅供参考和AC\n\n代码\n```java\nimport java.util.*;\n\npublic class Main {\n\tpublic static void main(String[] args) {\n\t\tScanner scan = new Scanner(System.in);\n\t\tStringBuilder s1 = new StringBuilder(500).append(scan.next());\n\t\tStringBuilder s2 = new StringBuilder(500).append(scan.next());\n\t\tSystem.out.println(strMul(sqrtStr(s1), sqrtStr(s2)));\n\t}\n\tstatic StringBuilder strMul(StringBuilder s1, StringBuilder s2) {//大数乘法\n\t\tint num[], i, j;\n\t\tnum = new int[500];\n\t\tfor(i=0; i<s1.length(); i++)//s计算保存到num中\n\t\t\tfor(j=0; j<s2.length(); j++)\n\t\t\t\tnum[i+j+1] += (s1.charAt(i)-'0') *  (s2.charAt(j)-'0');\n\t\tfor(i=s1.length()+s2.length()-1; i>0; i--)\n\t\t\tif(num[i]>=10) {\n\t\t\t\tnum[i-1] += num[i]/10;\n\t\t\t\tnum[i]%=10;\n\t\t\t}\n\t\tStringBuilder ans = new StringBuilder();\n\t\tfor(i=0; i<=s1.length()+s2.length()-1; i++) {\n\t\t\t//将num数存到ans字串中，注意进位为0的情况\n\t\t\tif(i==0 && num[i]!=0 || i!=0)\n\t\t\t\tans.append((char)(num[i] + '0'));\n\t\t}\n\t\treturn ans;\n\t}\n\tstatic boolean strCmp(StringBuilder s1, StringBuilder s2, int pos){//比较两字符串大小，pos代表应该在s1后面填几个零\n\t\tif(s1.length()+pos != s2.length())\n\t\t\treturn s1.length()+pos > s2.length();\n\t\telse\n\t\t\treturn s1.compareTo(s2)>0? true:false;\n\t}\n\tstatic StringBuilder sqrtStr(StringBuilder s) {//大数平方根取整\n\t\tint len;\n\t\tStringBuilder ans = new StringBuilder(500);\n\t\tif(s.length()%2 == 0)\n\t\t\tlen = s.length()/2;\n\t\telse\n\t\t\tlen = s.length()/2 + 1;\n\t\tfor(int i =0; i<len; i++) {\n\t\t\tans.append('0');\n\t\t\tfor(int j=0; j<=9; j++) {\n\t\t\t\t if(strCmp(strMul(ans,ans),s,2*(len-1-i)))//需要添加0的个数是2*（len-1-i）解析见上面\n\t\t                break;\n\t            ans.setCharAt(i, (char)(ans.charAt(i)+1));\n\t\t\t}\n\t\t\tans.setCharAt(i, (char)(ans.charAt(i)-1));\n\t\t}\n\t\treturn ans;\n\t}\n}\n```\n\n E 正文"}],"1815":[{"aid":"110427","title":"1815解题   C语言 （个人吐槽，这个输入结束后面的结束符不是回车也不是空格，反正是不在a到z区间的字符，之前用回车判断一直卡60分）","date":"2026-06-22","likes":0,"views":293,"md":"S 正文\n原题链接：蓝桥杯2014年第五届真题-排列序数\n\n Server-side output Markdown text\n#include <stdio.h>\nint main(void)\n{\n\tchar str[11];\n\tint str_num=0;\n\tint sum=0,quan=1,i,k;\n\n\tdo\n\t{\n\t\tstr[str_num] = getchar();\n\t\tstr_num++;\n\t}while(str[str_num-1]>='a'&&str[str_num-1]<='z');\n\tstr_num--;\n\n\t//好像是叫康托展开，就是设置权重前后比较\n\tfor(i=str_num-2;i>=0;i--)\n\t{\n\t\tquan=quan*(str_num-1-i);\n\t\tfor(k=i+1;k<str_num;k++)\n\t\t{\n\t\t\tif(str[i]>str[k])\n\t\t\t\tsum+=quan;\n\t\t}\n\t}\n\n\tprintf(\"%d\",sum);\n\n\treturn 0;\n}\n\n E 正文"},{"aid":"109296","title":"全排列（sf12f）","date":"2025-06-02","likes":0,"views":475,"md":"S 正文\n原题链接：蓝桥杯2014年第五届真题-排列序数\n\n解题思路:\n\n注意事项:\n\n参考代码:\n#include<bits/stdc++.h>\nusing namespace std;\nint main()\n{\n\tstring s1;\n    cin>>s1;\n    string s2=s1;  // s1原来   s2用于处理\n    sort(s2.begin(),s2.end());  // 排序\n    int cnt=0;\n    do{\n        if (s2==s1)\tbreak;  //退出循环\n        cnt++;\n    } while (next_permutation(s2.begin(), s2.end()));\n    cout<<cnt;\n}\n\n E 正文"},{"aid":"109248","title":"1815排列序数 C++：next_permutation()与do while","date":"2025-05-16","likes":0,"views":495,"md":"S 正文\n原题链接：蓝桥杯2014年第五届真题-排列序数\n\n解题思路:\n\n注意事项:\n\n参考代码:\n#include<bits/stdc++.h>\nusing namespace std;\nint main()\n{\n    string s;\n    cin>>s;\n    string original=s;  // 存储原始字符串\n\n    sort(s.begin(), s.end());  // 排序\n\n    int n=0;\n    do{\n                if (s==original)\n        \t\t        {\n                    break;  // 找到目标排列，退出循环\n\n                 }\n                n++;\n    } while (next_permutation(s.begin(), s.end()));\n    cout<<n;\n    return 0;\n}\n\n E 正文"},{"aid":"94806","title":"桥杯2014年第五届真题-排列序数用数组或字典会超内存","date":"2023-03-13","likes":0,"views":706,"md":"S 正文\n原题链接：蓝桥杯2014年第五届真题-排列序数\n\n解题思路:\n\nimport itertools\na=[]\ncount=0\nn=input()\nx=sorted(n)\nfor i in itertools.permutations(x):\n    s=\"\".join(i)\n    if s==n:\n        print(count)\n        break\n    else:\n        count+=1\n\n注意事项:\n\n参考代码:\n\n E 正文"},{"aid":"94233","title":"排列序数（c++）超短","date":"2023-02-23","likes":0,"views":614,"md":"S 正文\n原题链接：蓝桥杯2014年第五届真题-排列序数\n\n解题思路:\n\n注意事项:\n\n参考代码:\n#include<iostream>\n#include<algorithm>\n#include<cstring>\nusing namespace std;\nint main()\n{\nchar a[1000];int b,c=0;\ncin>>a;\nb=strlen(a);\nwhile(prev_permutation(a,a+b)){\n\tc++;\n}\ncout<<c;\n}\n\n E 正文"}],"1816":[{"aid":"85598","title":"字符串哈希解法(c++)","date":"2022-03-21","likes":0,"views":998,"md":"S 正文\n原题链接：蓝桥杯2014年第五届真题-重复模式\n\n解题思路:利用字符串哈希确定字符子串出现的次数，当次数大于等于2时，将答案更新\n\n注意事项:\n\n参考代码:\n#include\n#include\n#include\n#include\nusing namespace std;\nunordered_map\nconst int N = 200003,M=131;\n\ntypedef unsigned long long ULL;//用ull实际上有一个取模的作用\nULL h[N],p[N];//h[N]存储前缀和，P【N】存储幂\nchar x[N];//存储字符串\nint l1,r1,l2,r2;\n\nULL query(int l, int r){//返回字符哈希映射值\n    ULL a = h[r] - h[l-1]*p[r-l+1];\n    //类似于h[l,r]=h[r]−h[l−1]×Pr−l+1h[l,r]=h[r]−h[l−1]×P[r−l+1]   45 = 12345 - 123*100\n    return a;\n}\nint main()\n{\n    int ans = 0;\n    cin >> x+1;//从一开始读入(因为要求前缀和)\n\n    p[0] = 1;//0次幂等于1\n    for (int i = 1; i <= strlen(x + 1); i ++ ){\n        p[i] = p[i-1] * M;\n        h[i] = h[i-1] * M + x[i];\n    }\n\n    for(int len = 1; len <= strlen(x + 1); len ++){\n        for(int l = 1; l + len <= strlen(x + 1); l++){\n            int r = l + len;\n            int zhi = query(l,r);\n                maps[zhi] ++;\n                if(maps[zhi] >= 2){\n                    if(len > ans){\n                        ans = len;\n                    }\n                }\n        }\n    }\n    cout << ans + 1;\n    return 0;\n\n}\n\n E 正文"},{"aid":"85082","title":"做题记录2022.3.10(ac:100%)","date":"2022-03-10","likes":0,"views":757,"md":"S 正文\n原题链接：蓝桥杯2014年第五届真题-重复模式\n\n解题思路:暴力,但不完全暴力\n\n注意事项:\n\n参考代码:\nstring = input().strip()\nlength = len(string)\nmax_len = float(\"-inf\")\n# 参考了另一位笔者的代码,他没有写注释,虽然程序很简短,但细节还是需要思考的,本人只略做修改和注释,方便理解\nfor i in range(1, length + 1):  # 遍历子串的长度\n    for j in range(length - i + 1):  # 遍历起始位置\n        if string.find(string[j:j + i], j + 1) != -1 and len(string[j:j + i]) > max_len:\n            # 当前起始位置能取到的字符串(出现了一次)能否在起始位置+1之后的部分找到相同的,即出现两次及以上,且长度大于当前最大长度\n            max_len = len(string[j:j + i])\n        else:  # 此处break思路非常巧妙,代码实际上只求解了每个位置能出现两次的字符串的最大长度,而不是遍历所有的子串,所以平均时间复杂度是要远远优于O(n**2)\n            break\nprint(max_len)\n\n E 正文"},{"aid":"73277","title":"蓝桥杯2014年第五届真题-重复模式-题解（Java代码）正则解法","date":"2020-10-14","likes":0,"views":891,"md":"S 正文\n原题链接：蓝桥杯2014年第五届真题-重复模式\n\n Server-side output Markdown text\n\timport java.util.*;\n\timport java.util.regex.*;\n\n\tpublic class Main {\n\t\tpublic static void main(String[] args) {\n\t\t\tScanner scanner = new Scanner(System.in);\n\n\t\t\tint sum = 0;\n\t\t\tString arr = scanner.next();\n\t\t\t// i : 截取长度，题意求最长，所以从最长开始递减\n\t\t\tfor (int i = arr.length() - 1; i > 0; i--) {\n\t\t\t\tfor (int j = 0; j + i <= arr.length(); j++) {\n\t\t\t\t\t/**\n\t\t\t\t\t * j : 截取起点\n\t\t\t\t\t * 从 j开始截取，截取长度为 i\n\t\t\t\t\t */\n\t\t\t\t\tString item = arr.substring(j, j + i);\n\t\t\t\t\t/**\n\t\t\t\t\t * (?=pattern)\n\t\t\t\t\t * 正向肯定预查（look ahead positive assert），在任何匹配pattern的字符串开始处匹配查找字符串。\n\t\t\t\t\t * 这是一个非获取匹配，也就是说，该匹配不需要获取供以后使用。\n\t\t\t\t\t * 例如，\"Windows(?=95|98|NT|2000)\"能匹配\"Windows2000\"中的\"Windows\"，但不能匹配\"Windows3.1\"中的\"Windows\"。\n\t\t\t\t\t * 预查不消耗字符，也就是说，在一个匹配发生后，在最后一次匹配之后立即开始下一次匹配的搜索，而不是从包含预查的字符之后开始。\n\t\t\t\t\t */\n\t\t\t\t\tPattern p = Pattern.compile(String.format(\"(?=(%s))\", item));\n\t\t\t\t\t/**\n\t\t\t\t\t * 捕获组\n\t\t\t\t\t * 捕获组是把多个字符当一个单独单元进行处理的方法，它通过对括号内的字符分组来创建。\n\t\t\t\t\t */\n\t\t\t\t\tMatcher m = p.matcher(arr);\n\t\t\t\t\tfor (int k = 0; m.find(); k++) {\n\t\t\t\t\t\tif (k > 0) {\n\t\t\t\t\t\t\t// 捕获到的数量大于2时，即是符合题意，记录匹配的最长字符串\n\t\t\t\t\t\t\tsum = Math.max(sum, item.length());\n\t\t\t\t\t\t}\n\t\t\t\t\t}\n\t\t\t\t}\n\t\t\t}\n\t\t\tSystem.out.print(sum);\n\t\t}\n\t}\n\n E 正文"},{"aid":"70884","title":"蓝桥杯2014年第五届真题-重复模式-题解（C++代码）","date":"2020-06-28","likes":0,"views":1113,"md":"S 正文\n原题链接：蓝桥杯2014年第五届真题-重复模式\n\n Server-side output Markdown text\n```\n#include <iostream>\nusing namespace std;\n\nint main()\n{\n\tstring s;\n\tcin>>s;\n\tint l=s.size();\n\n\tint res=-100;\n\tfor(int i=0;i<=l-1;i++)\n\t{\n\t\tfor(int j=0;j<l;j++)\n\t\t{\n\t\t\tint f=0;\n\t\t\tstring t=\"\";\n\t\t\tfor(int y=j;y<=j+i;y++) t+=s[y];\n\t\t\tfor(int x=0;x<l;x++)\n\t\t\t{\n\t\t\t\tif(j==x) continue;\n\t\t\t\tstring m=\"\";\n\t\t\t\tfor(int h=x;h<=x+i;h++) m+=s[h];\n\t\t\t\tif(t==m) f++;\n\t\t\t}\n\t\t\tif(f>=1&&i>res)\n\t\t\t\tres=i;\n\t\t}\n\t}\n\tif(l==1||res==-100) cout<<1;\n\telse\n\t\tcout<<res+1;\n\treturn 0;\n}\n```\n\n E 正文"},{"aid":"69795","title":"蓝桥杯2014年第五届真题-重复模式-题解(C语言代码)","date":"2020-04-25","likes":1,"views":1280,"md":"S 正文\n原题链接：蓝桥杯2014年第五届真题-重复模式\n\n Server-side output Markdown text\n    #include <stdio.h>\n    #include <string.h>\n\n    int main(void)\n    {\n    \tchar str[1000];\n    \tint i = 0, j = 0, max = 0, ner = 0;\n    \tscanf(\"%s\", str);\n    \tint len = strlen(str);\n    \tfor (i = 0; i < len-1; ++i) {\n    \t\tfor (j = i+1, ner = 0; j < len; ++j) {\n    \t\t\tif (str[i+ner]==str[j]) {\n    \t\t\t\t++ner;\n    \t\t\t\tif (str[i+ner]!=str[j+1]) {\n    \t\t\t\t\tmax = max>ner?max:ner;\n    \t\t\t\t\tner = 0;\n    \t\t\t\t}\n    \t\t\t}\n    \t\t}\n    \t}\n    \tprintf(\"%d\", max);\n    \treturn 0;\n    }\n\n E 正文"}],"1818":[{"aid":"77559","title":"1818: 蓝桥杯2014年第五届真题-生物芯片（Python3) 3行","date":"2021-03-18","likes":0,"views":1182,"md":"S 正文\n原题链接：蓝桥杯2014年第五届真题-生物芯片\n\n解题思路:\n无\n\n注意事项:\n无\n\n参考代码:\nn, l, r = map(int, input().split())\ntemp = sum(1 for i in range(l, r + 1) if (i ** (1/2)).is_integer())\nprint(r - l + 1 - temp)\n\n E 正文"},{"aid":"75789","title":"蓝桥杯2014年第五届真题-生物芯片-题解（Java代码）","date":"2021-01-25","likes":0,"views":1201,"md":"S 正文\n原题链接：蓝桥杯2014年第五届真题-生物芯片\n\n一开始想的是直接暴力破解 然后数量少一点还是可以但是数量多了就有点问题；\n\nimport java.util.Scanner;;\n    public class Main {\n        public static void main(String[] args) {\n            Scanner scanner = new Scanner(System.in);\n            int a=scanner.nextInt();\n            int b=scanner.nextInt();\n            int c=scanner.nextInt();\n            int sum=0;\n            for (int i = b; i <=c; i++) {\n                boolean isFlag=false;\n                for (int j = 2; j <= a; j++) {\n                    if (i%j==0) {\n                        if (isFlag==true) {\n                            isFlag=false;\n                        }else if(isFlag==false){\n                            isFlag=true;\n                        }\n                    }\n                }\n                if (isFlag==true) {\n                    sum++;\n                }\n            }\n            System.out.println(sum);\n    }\n}然后看了下写题解的大佬们写的 真的牛思路可以看第一个c++题解 我是水个题解\n\n    import java.util.Scanner;\n    public class Main {\n        public static void main(String[] args) {\n            Scanner sc = new Scanner(System.in);\n            long n = sc.nextLong();\n            long l = sc.nextLong();\n            long r = sc.nextLong();\n            long a=r-l+1;\n            long b=(long)Math.sqrt(r)-(long)Math.sqrt(l);\n            System.out.println(a-b);\n        }\n    }\n\n E 正文"},{"aid":"73572","title":"蓝桥杯2014年第五届真题-生物芯片-题解（Python代码）","date":"2020-11-05","likes":0,"views":1231,"md":"S 正文\n原题链接：蓝桥杯2014年第五届真题-生物芯片\n\n Server-side output Markdown text\n```python\nimport math\nN,L,R = map(int,input().split())\ncount = 0\nfor i in range(L,R+1):\n    if int(math.sqrt(i))**2!=i:# 当n**2等于i时，则说明灯点一下从亮边暗，其他情况都是点两下\n        count += 1\nprint(count) #虽然题目说灯开始时关闭的，但是开灯是从2开始的，转化后变成了，灯开始为亮，从1开始开灯\n```\n\n E 正文"},{"aid":"73131","title":"蓝桥杯2014年第五届真题-生物芯片-题解（C++代码）","date":"2020-10-09","likes":0,"views":1301,"md":"S 正文\n原题链接：蓝桥杯2014年第五届真题-生物芯片\n\n Server-side output Markdown text\n## 结论：\n ### $完全平方数的因子数为奇数$\n\n<br>\n\n### 解题思路：一个灯是否开着与它的因子个数有关系，如果它的因子个数为奇数，则关闭。完全平方数的因子数是奇数的，但是题目说了1的倍数不算，那么去掉1这个因子，完全平方数的因子数为偶数，只需要把L ~ R区间的因子个数减去L ~ R区间的完全平方数即可。一个区间的完全平方数为$sqrt(R)-sqrt(L)$。\n<br>\n\n### PS：要强转格式\n\n```cpp\n#include<bits/stdc++.h>\n#define x first\n#define y second\n#define mem(h) memset(h,-1,sizeof h)\n#define mcp(a,b) memcpy(a,b,sizeof b)\nusing namespace std;\ntypedef long long LL;\ntypedef unsigned long long ull;\ntypedef pair<int,int>PII;\ntypedef pair<double,double>PDD;\nnamespace IO{\n\tinline LL read(){\n\t\tLL o=0,f=1;char c=getchar();\n\t\twhile(c<'0'||c>'9'){if(c=='-')f=-1;c=getchar();}\n\t\twhile(c>='0'&&c<='9'){o=o*10+c-'0';c=getchar();}\n\t\treturn o*f;\n\t}\n}using namespace IO;\n//#############以上是自定义技巧（可忽略）##########\nconst int N=1e3+7,M=2e5+7,INF=0x3f3f3f3f,mod=1e8+7,P=131;\nLL n,L,R;\nint main(){\n\tcin>>n>>L>>R;\n\tLL sum=R-L+1;\n\tLL sq_num=(LL)sqrt(R)-(LL)sqrt(L);\n\tcout<<sum-sq_num<<endl;\n\treturn 0;\n}\n```\n\n E 正文"},{"aid":"67504","title":"蓝桥杯2014年第五届真题-生物芯片-题解(C语言代码)---怀疑隔壁C++写的有遗漏的错误点，解释详细","date":"2020-03-05","likes":0,"views":1434,"md":"S 正文\n原题链接：蓝桥杯2014年第五届真题-生物芯片\n\n Server-side output Markdown text\n怀疑隔壁答案错误的地方：\n隔壁两个C++答案输入（20,9,16）结果是7，我的代码结果是6。正确的结果应该是灭掉首尾2盏，保留中间6盏，答案是6。应当注意完全平方数个数的处理\n解题思路：\n1.看数据范围最大可达10^15次方，暴力跑数组一定会超时，故肯定存在巧计\n\n----\n2.观察一下可以发现，每个灯，如果变换偶数次就是灭的，变换奇数次就是亮的。那么我们求结果可以直接拿R-L+1（R~L的灯个数）减去变换偶数次的灯，那么剩下的就是亮的灯。\n\n---\n3.那么我们怎么求出变换次数是偶数次的灯呢？其实，所谓变换次数，就是这个灯的因数个数减一，因数个数减一是多少就变换多少次。\n（为什么要减1请看下一条）\n\n---\n4.那么我们怎么知道因数的个数是奇数还是偶数？规律是这样的：完全平方数的因数个数是奇数，非完全平方数的个数是偶数。什么意思呢？就是4能被1,2,4整除，因数个数是3；9能被1,3,9整除，因数个数也是3，自己列举一下就可以发现完全平方数的因数个数全都是奇数。但是题目中，不会对1整除，所以完全平方数因数个数是奇数就意味着变换偶数次，完全平方数因数个数是偶数就意味着变换奇数次。\n**原理:随便举个数字16为例，一般的数字都是两两凑成一对的积等于结果，你看，比如1x16=16,2x8=16。但是偏偏他多了一个4x4=16。它自己就可以凑成一对。所以它因数个数是5个，是个奇数。所有的完全平方数都一样，因数是奇数**\n\n---\n5.现在我们知道，在L~R之间，只有某个灯的变换次数是偶数的会熄灭，即是完全平方数的灯会熄灭。我们只需要统计L~R之间有多少个完全平方数，最后减掉它就行了。\nL~R之间完全平方数个数求法：对L和R分别开方。根号L和根号R之间，有多少个整数，L和R之间就有多少个完全平方数。\n##### 原理：例如求100~200之间的完全平方数个数，根号100等于10，根号200等于14.14。10~14.14之间的整数，它们各自的平方都不会超过100~200的范围，个数是5个。\n\n---\n6.最后的结果就是R~L灯泡的个数减去，根号L和根号R之间的整数result。\n式子:（R-L+1）- result。下面请看代码\n```cpp\n#include <stdio.h>\n#include <math.h>\nlong long N,L,R;\nint get_num(double first,double second)\n{\n\tint count_=0;\n\tfor(int i=first;i<=second;i++)\n\t{\n\t\tcount_++;\n\t}\n\tif(first-(int)first>0) count_--;\n\treturn count_;\n}\nint main()\n{\n\tscanf(\"%ld %ld %ld\",&N,&L,&R);\t//数据读入\n\tdouble first= sqrt(L);\n\tdouble second=sqrt(R);\t//最大15次方，开过根号不会爆范围的\n\tint result=get_num(first,second);\t//判断first到second两个小数之间有多少个整数\n\tprintf(\"%d\",R-L+1-result);\n\treturn 0;\n}\n```\n\n E 正文"}],"1819":[{"aid":"95596","title":"蓝桥杯2014年第五届真题-Log大侠","date":"2023-04-04","likes":0,"views":520,"md":"S 正文\n原题链接：蓝桥杯2014年第五届真题-Log大侠\n\n解题思路:\n\n注意事项:\n\n参考代码:\nfrom math import*\nn,m = map(int,input().split())\nL = list(map(int,input().split()))\nfor i in range(m):\n    a,b = map(int,input().split())\n    for j in range(a-1,b):\n        L[j] = int(log(L[j],2))+1\n    print(sum(L))\n\n E 正文"},{"aid":"73134","title":"蓝桥杯2014年第五届真题-Log大侠-题解（C++代码）","date":"2020-10-09","likes":0,"views":1028,"md":"S 正文\n原题链接：蓝桥杯2014年第五届真题-Log大侠\n\n Server-side output Markdown text\n### 解题思路：由于此题的数据有点水，所以暴力就可以过，正解是线段树，贴上代码自行理解。\n\n<br>\n\n**暴力代码**\n\n```cpp\n#include<bits/stdc++.h>\n#define x first\n#define y second\n#define mem(h) memset(h,-1,sizeof h)\n#define mcp(a,b) memcpy(a,b,sizeof b)\nusing namespace std;\ntypedef long long LL;\ntypedef unsigned long long ull;\ntypedef pair<int,int>PII;\ntypedef pair<double,double>PDD;\nnamespace IO{\n\tinline LL read(){\n\t\tLL o=0,f=1;char c=getchar();\n\t\twhile(c<'0'||c>'9'){if(c=='-')f=-1;c=getchar();}\n\t\twhile(c>='0'&&c<='9'){o=o*10+c-'0';c=getchar();}\n\t\treturn o*f;\n\t}\n}using namespace IO;\n//#############以上是自定义技巧（可忽略）##########\nconst int N=1e5+7,M=2e5+7,INF=0x3f3f3f3f,mod=1e8+7,P=131;\nint n,m;\nint a[N];\nint main(){\n\tcin>>n>>m;\n\tfor(int i=1;i<=n;i++)cin>>a[i];\n\tint l,r;\n\twhile(m--){\n\t\tint sum=0;\n\t\tcin>>l>>r;\n\t\tfor(int i=l;i<=r;i++)a[i]=(int)log2(a[i])+1;\n\t\tfor(int i=1;i<=n;i++)sum+=a[i];\n\t\tcout<<sum<<endl;\n\t}\n\treturn 0;\n}\n```\n\n----------------------\n**线段树代码**\n```cpp\n#include<bits/stdc++.h>\n#define x first\n#define y second\n#define mem(h) memset(h,-1,sizeof h)\n#define mcp(a,b) memcpy(a,b,sizeof b)\nusing namespace std;\ntypedef long long LL;\ntypedef unsigned long long ull;\ntypedef pair<int,int>PII;\ntypedef pair<double,double>PDD;\nnamespace IO{\n\tinline LL read(){\n\t\tLL o=0,f=1;char c=getchar();\n\t\twhile(c<'0'||c>'9'){if(c=='-')f=-1;c=getchar();}\n\t\twhile(c>='0'&&c<='9'){o=o*10+c-'0';c=getchar();}\n\t\treturn o*f;\n\t}\n}using namespace IO;\n//#############以上是自定义技巧（可忽略）##########\nconst int N=1e5+7,M=2e5+7,INF=0x3f3f3f3f,mod=1e8+7,P=131;\nstruct node{\n\tint l,r,sum;\n}tr[N<<2];\nint n,m,a[N];\nvoid push_up(int rt){//更新节点的sum\n\ttr[rt].sum=tr[rt<<1].sum+tr[rt<<1|1].sum;\n}\nvoid build(int rt,int l,int r){//划分线段树\n\ttr[rt]={l,r};\n\tif(l==r){\n\t\ttr[rt].sum=a[l];\n\t\treturn ;\n\t}\n\tint mid=l+r>>1;\n\tbuild(rt<<1,l,mid),build(rt<<1|1,mid+1,r);\n\tpush_up(rt);\n}\nvoid modify(int rt,int l,int r){//修改操作\n\tif(tr[rt].l==tr[rt].r){\n\t\ttr[rt].sum=(int)log2(tr[rt].sum)+1;\n\t\treturn ;\n\t}\n\tint mid=tr[rt].l+tr[rt].r>>1;\n\tif(l<=mid)modify(rt<<1,l,r);\n\tif(r>mid)modify(rt<<1|1,l,r);\n\tpush_up(rt);\n}\nint query(int rt,int l,int r){//查询操作\n\tif(tr[rt].l<=l&&tr[rt].r<=r){\n\t\treturn tr[rt].sum;\n\t}\n\tint mid=tr[rt].l+tr[rt].r>>1;\n\tint sum=0;\n\tif(l<=mid)sum+=query(rt,l,r);\n\tif(r>mid)sum+=query(rt,l,r);\n\treturn sum;\n}\nint main(){\n\tcin>>n>>m;\n\tfor(int i=1;i<=n;i++)cin>>a[i];\n\tbuild(1,1,n);\n\tint l,r;\n\twhile(m--){\n\t\tcin>>l>>r;\n\t\tmodify(1,l,r);\n\t\tcout<<query(1,1,n)<<endl;\n\t}\n\treturn 0;\n}\n```\n\n E 正文"},{"aid":"66721","title":"蓝桥杯2014年第五届真题-Log大侠-题解(Java代码)","date":"2020-02-21","likes":0,"views":994,"md":"S 正文\n原题链接：蓝桥杯2014年第五届真题-Log大侠\n\n Server-side output Markdown text\n```java\nimport java.util.Scanner;\n\npublic class Main {\n\tpublic static void main(String[] args) {\n\t\tScanner sc = new Scanner(System.in);\n\t\tint n = sc.nextInt();\n\t\tint[] a = new int[n+1];\n\t\tint m = sc.nextInt();\n\t\tfor(int i = 1;i<=n;i++){\n\t\t    a[i] = sc.nextInt();\n\t\t}\n\t\tfor(int i = 0;i<m;i++){\n\t\t    int l = sc.nextInt();\n\t\t    int r = sc.nextInt();\n\t\t    int res = 0;\n\t\t    for(int j = 1;j<=n;j++){\n\t\t        if(j>=l&&j<=r){\n\t\t           a[j] = (int)(Math.log((double)a[j]) / Math.log(2)) + 1;\n\t\t           res += a[j];\n\t\t        }else{\n\t\t            res += a[j];\n\t\t        }\n\t\t    }\n\t\t    System.out.println(res);\n\t\t}\n\t}\n}\n```\n\n E 正文"},{"aid":"65985","title":"蓝桥杯2014年第五届真题-Log大侠-题解(Python代码)","date":"2020-02-12","likes":0,"views":1282,"md":"S 正文\n原题链接：蓝桥杯2014年第五届真题-Log大侠\n\n Server-side output Markdown text\n2020-02-12 21:22:11 星期三\n简单题，按照题目意思直接写就行了。\n```python\ndef input_():\n    n,m = map(int,input().split())\n    ls = list(map(int,input().split()))\n    while True:\n        s,x = list(map(int,input().split()))\n        ls = log(n,m,ls,s,x)\n\ndef log(n,m,ls,s,x):\n    import math\n    for i in range(s-1,x):\n        a = math.log(ls[i],2)+1\n        ls[i] = int(a)\n    print(sum(ls))\n    return ls\n\ninput_()\n```\n\n E 正文"},{"aid":"59866","title":"蓝桥杯2014年第五届真题-Log大侠 （C++代码）","date":"2019-05-16","likes":0,"views":1235,"md":"S 正文\n原题链接：蓝桥杯2014年第五届真题-Log大侠\n\n解题思路:\n注意事项:\n\n参考代码:\n#include <bits/stdc++.h>\nusing namespace std;\nconst int maxn = 1E5+2;\nint _log[maxn],a[maxn];\nint n,m,sum;\nint p(int n)\n{\n\treturn !n ? 1 : p(n-1)<<1;\n}\nint main()\n{\n\tcin >> n >> m;\n\tint l,r,l1,r1;\n\tl = 1;\n\t//打表maxn内的对数 O(n)\n\tfor(int i=1; p(i-1)<=maxn; ++i)\n\t{\n\t\tr = p(i);\n\t\tfor(int j=l; j<r&&j<=maxn; ++j)\n\t\t{\n\t\t\t_log[j] = i;\n\t\t}\n\t\tl = r;\n\t}\n\tfor(int i=1; i<=n; ++i)\n\t{\n\t\tcin >> a[i];\n\t\tsum += a[i];\n\t}\n\tfor(int i=0; i<m; ++i)\n\t{\n\t\tcin >> l1 >> r1;\n\t\tfor(int j=l1; j<=r1; ++j)\n\t\t{\n\t\t\tsum -= a[j];\n\t\t\ta[j] = _log[a[j]];\n\t\t\tsum += a[j];\n\t\t}\n\t\tcout << sum << endl;\n\t}\n\treturn 0;\n}\n\n E 正文"}],"1821":[{"aid":"107861","title":"蓝桥杯2014年第五届真题-拼接平方数 （C++代码）简单通解","date":"2024-12-08","likes":0,"views":493,"md":"S 正文\n原题链接：蓝桥杯2014年第五届真题-拼接平方数\n\n解题思路:\n\n注意事项:\n\n参考代码:\n//1.先求所有平方数，缩小范围\n//2.只能拆分成左边数字和右边数字，通过求商和求余获得\n#include<iostream>\n#include<cmath>\nusing namespace std;\nbool fun(int a)\n{\n    int temp = (int)sqrt(a)*(int)sqrt(a);\n    if(temp == a)return true;\n    else return false;\n}\nint main()\n{\n    int a,b;\n    cin>>a>>b;\n    //先求平方数，缩小范围\n    int min = ceil(sqrt(a));\n    int max = floor(sqrt(b));\n    for(int i=min;i<=max;i++)\n    {\n        int temp =i*i;\n        for(int j=1;temp/(int)pow(10,j)>0;j++)\n        {\n            if(temp%(int)pow(10,j)==0)continue;\n            //求商－－得出左边的数，求余－－得出右边的数\n            if(fun(temp/(int)pow(10,j))&&fun(temp%(int)pow(10,j)))\n            {\n                cout<<i*i<<endl;\n                break;\n            }\n        }\n\n    }\n    return 0;\n}\n\n E 正文"},{"aid":"107131","title":"拼接平方数","date":"2024-11-14","likes":1,"views":480,"md":"S 正文\n原题链接：蓝桥杯2014年第五届真题-拼接平方数\n\n Server-side output Markdown text\n```python\nn, m = map(int, input().split())\nls = [i for i in range(n, m + 1) if int(i**0.5)**2 == i]\nfor i in ls:\n    if i < 10:\n        continue\n    else:\n        for j in range(1,len(str(i))):\n            if int(str(i)[j:])==0:\n                break\n            elif int(int(str(i)[0:j])**0.5)**2 == int(str(i)[0:j]) and int(int(str(i)[j:])**0.5)**2 == int(str(i)[j:]):\n                print(i)\n\n```\n\n E 正文"},{"aid":"102610","title":"java--study||O.o","date":"2024-02-08","likes":0,"views":551,"md":"S 正文\n原题链接：蓝桥杯2014年第五届真题-拼接平方数\n\n参考代码:\nimport java.util.Scanner;\n\npublic class Main\n{\tpublic static void main(String[] args)\n    {\tScanner scanner = new Scanner(System.in);\n    \tp(scanner.nextInt(), scanner.nextInt());\n    }\n\tpublic static void p(int a, int b)\n\t{\tfor(int i = a; i <= b; i++)\n\t\t\tif(judge(i) && splitJudge(i))\n\t\t\t\tSystem.out.println(i);\n\t}\n\tpublic static boolean splitJudge(int in)\n\t{\tString original = new String().valueOf(in);\n\t\tint n = original.length();\n\t\tfor(int i = 1; i < n; i++)\n\t\t{\tString s1 = original.substring(0, i);\n\t\t\tString s2 = original.substring(i);\n\t\t\tint a = Integer.parseInt(s1);\n\t\t\tint b = Integer.parseInt(s2);\n\t\t\tif(judge(a) && judge(b))\n\t\t\t\treturn true;\n\t\t}\n\t\treturn false;\n\t}\n\tpublic static boolean judge(int x)\n\t{\tif(x == 0)\n\t\t\treturn false;\n\t\tdouble a = Math.sqrt(x);\n\t\tint b = (int)a;\n\t\tif(a == b)\n\t\t\treturn true;\n\t\treturn false;\n\t}\n}\n\n E 正文"},{"aid":"101383","title":"java 蓝桥杯2014年第五届真题-拼接平方数","date":"2023-12-31","likes":0,"views":556,"md":"S 正文\n原题链接：蓝桥杯2014年第五届真题-拼接平方数\n\n解题思路:\n\n注意事项:\n\n参考代码:\nimport java.util.Scanner;\n\npublic class Main {\n    public static void main(String[] args) {\n        Scanner sc = new Scanner(System.in);\n        int a = sc.nextInt();\n        int b = sc.nextInt();\n        for (int i = a; i <= b; i++) {\n            int z = f(i);\n            if (z != 0) {\n                for (int j = 1; j < (z + \"\").length(); j++) {\n                    String s = z + \"\";\n                    int v1 = Integer.parseInt(s.substring(0, j));\n                    int v2 = Integer.parseInt(s.substring(j));\n                    if (Math.sqrt(v1) % 1 == 0 && Math.sqrt(v2) % 1 == 0 && v1 > 0 && v2 > 0) {\n                        System.out.println(z);\n                    }\n                }\n            }\n        }\n    }\n\n    public static int f(int i) {\n        int z = 0;\n        for (int m = 1; m <= Math.sqrt(i); m++) {\n            if (m * m == i) {\n                z = i;\n                break;\n            }\n        }\n        return z;\n    }\n}\n\n E 正文"},{"aid":"95026","title":"蓝桥杯专题系列-1821（Python）","date":"2023-03-19","likes":0,"views":537,"md":"S 正文\n原题链接：蓝桥杯2014年第五届真题-拼接平方数\n\n解题思路:模拟题\n\n注意事项:注意数据类型间的转化\n\n参考代码:\nn, m = map(int, input().split())\nlow, high = int(pow(n, 0.5)), int(pow(m, 0.5) + 1)\nlst = [i ** 2 for i in range(1, high)]\nlst_ = list(filter(lambda x : x > n, lst))\nfor data in lst_ :\n    data = str(data)\n    for i in range(1, len(data)) :\n        n1, n2 = data[:i], data[i :]\n        n1, n2 = int(n1), int(n2)\n        if n2 == 0 :\n            break\n        else :\n            if n1 in lst and n2 in lst :\n                print(data)\n                break\n\n E 正文"}],"1822":[{"aid":"56648","title":"蓝桥杯2014年第五届真题-套娃 （C++代码）","date":"2018-12-13","likes":1,"views":1523,"md":"S 正文\n原题链接：蓝桥杯2014年第五届真题-套娃\n\n解题思路:\n并查集吧\n为毛超时啊？？\n最强召唤魔法，地表最强召唤兽~@地表最强召唤兽\n\n注意事项:\n\n参考代码:\n#include <iostream>\n#include <stdio.h>\n#include <vector>\n#include <map>\n\nusing namespace std;\n\nmap<int, int> dollSet;\n\nint Q(int x)\n{\n\tint ans = 0;\n\twhile (dollSet[x] != x && dollSet[x] != 0)\n\t{\n\t\tx = dollSet[x];\n\t\tans += 1;\n\t}\n\treturn ans;\n}\n\nint P(int x, int n)\n{\n\tint count = 0;\n\tint preX = x;\n\twhile (dollSet[x] != x && dollSet[x] != 0)\n\t{\n\t\t//找前驱是x的结点的值，前驱->前驱的前驱\n\t\tfor (map<int, int>::iterator it = dollSet.begin(); it != dollSet.end(); it++)\n\t\t\tif (it->second == x)\n\t\t\t\tit->second = dollSet[x];\n\t\tpreX = x;\n\t\tx = dollSet[x];\n\t\tcount += 1;\n\t}\n\n\t//解开根结点，构造一个虚拟的“根结点”\n\tfor (map<int, int>::iterator it = dollSet.begin(); it != dollSet.end(); it++)\n\t\tif (it->second == n)\n\t\t\tit->second = 0;\n\n\treturn count;\n}\n\nint main(void)\n{\n\tint n,m;\n\tcin >> n >> m;\n\tfor (int i = 1; i <= n - 1; i++)\n\t{\n\t\tint a,b;\n\t\tcin >> a >> b;\n\t\tdollSet[b] = a;\n\t}\n\tdollSet[n] = n;\n\n\tfor (int i = 0; i < m; i++)\n\t{\n\t\tchar ch;\n\t\tint x;\n\t\tcin >> ch >> x;\n\t\tswitch (ch)\n\t\t{\n\t\tcase 'Q':\n\t\t\tcout << Q(x) << \"\\n\";\n\t\t\tbreak;\n\t\tcase 'P':\n\t\t\tcout << P(x, n) << \"\\n\";\n\t\t\tbreak;\n\t\t}\n\t}\n\n    return 0;\n}\n\n E 正文"}],"1824":[{"aid":"102619","title":"java--study||O.o","date":"2024-02-08","likes":0,"views":575,"md":"S 正文\n原题链接：蓝桥杯2014年第五届真题-稍大的串\n\n参考代码:\nimport java.util.Arrays;\nimport java.util.Scanner;\n\npublic class Main\n{\tpublic static void main(String[] args)\n    {\tScanner scanner = new Scanner(System.in);\n    \tSystem.out.println(next(scanner.next()));\n    }\n\tpublic static String next(String in)\n\t{\n\t\tchar []s = in.toCharArray();\n\t\tint i = s.length - 2;\n\t\twhile(i >= 0 && s[i] >= s[i + 1])\n\t\t\ti--;\n\t\tif(i < 0)\n\t\t\treturn in;\n\t\tint j = s.length - 1;\n\t\twhile(j > i && s[j] <= s[i])\n\t\t\tj--;\n\t\tswap(s, i, j);\n\t\tArrays.sort(s, i + 1, s.length);\n\t\tString res = \"\";\n\t\tfor(char c: s)\n\t\t\tres += c;\n\t\treturn res;\n\t}\n\tpublic static void swap(char []arr, int i, int j)\n\t{\tchar t = arr[i];\n\t\tarr[i] = arr[j];\n\t\tarr[j] = t;\n\t}\n}\n\n E 正文"},{"aid":"85077","title":"做题记录2022.3.10(ac:100%)","date":"2022-03-10","likes":0,"views":654,"md":"S 正文\n原题链接：蓝桥杯2014年第五届真题-稍大的串\n\n解题思路:我也没有思路,写的题多了,也便有了套路\n按照代码注释的交换字符就能得到下一个字典序字符串\n\n注意事项:\n\n参考代码:\ntemp = input().strip()\nstring = list(temp)\nlength = len(string)\n\ni = length - 2  # 至少两个元素才能交换,排序\nwhile i >= 0 and string[i] >= string[i + 1]:  # 从后往前找到第一个小于后面元素的a[i]\n    i -= 1\n\nif i >= 0:  # 若整个数组为降序,则在a[i]之后不存在比a[i]大的元素,不用执行while\n    j = length - 1\n    while j >= i and string[j] <= string[i]:  # 从后往前找到第一个大于a[i]的元素\n        j -= 1\n    string[i], string[j] = string[j], string[i]\n\nleft, right = i + 1, length - 1\nwhile left < right:  # 因为原来顺序是降序,将i后的升序排序只需要逆转即可\n    string[left], string[right] = string[right], string[left]\n    left += 1\n    right -= 1\nprint(string)\n\n E 正文"},{"aid":"73538","title":"蓝桥杯2014年第五届真题-稍大的串-题解（Python代码）","date":"2020-11-03","likes":0,"views":1045,"md":"S 正文\n原题链接：蓝桥杯2014年第五届真题-稍大的串\n\n Server-side output Markdown text\n```python\nk=list(input().strip())\n\nfor i in range(len(k)-2,-1,-1):\n    if k[i]>=k[i+1]:\n        continue\n    elif k[i]<k[i+1]:\n        for j in range(len(k)-1,-1,-1):\n            if k[i]<k[j]:\n                k[i],k[j]=k[j],k[i]\n                break\n        strk=k[i+1:]\n        strk.sort()\n        print(\"\".join(k[:i+1]+strk))\n        break\n```\n\n E 正文"},{"aid":"70941","title":"蓝桥杯2014年第五届真题-稍大的串-题解（C++代码）","date":"2020-07-01","likes":0,"views":1138,"md":"S 正文\n原题链接：蓝桥杯2014年第五届真题-稍大的串\n\n Server-side output Markdown text\n```\n#include <iostream>\n#include <algorithm>\n#include <string.h>\nusing namespace std;\n\nchar a[1005];\nint main()\n{\n\tcin>>a;\n\tint len=strlen(a);\n\tint cnt=0;\n\tdo\n\t{\n\t\tif(cnt==1)\n\t\t{\n\t\t\tfor(int i=0;i<len;i++)\n\t\t\t{\n\t\t\t\tcout<<a[i];\n\t\t\t}\n\t\t\tcout<<endl;\n\t\t\tbreak;\n\t\t}\n\t\tcnt++;\n\t}while(next_permutation(a,a+len));\n\treturn 0;\n}\n```\n\n E 正文"},{"aid":"67562","title":"蓝桥杯2014年第五届真题-稍大的串-题解(C++代码)---STL现成函数调用","date":"2020-03-06","likes":0,"views":1584,"md":"S 正文\n原题链接：蓝桥杯2014年第五届真题-稍大的串\n\n Server-side output Markdown text\nnext_permutation函数自动生成下一个排列。pre_permutation自动生成上一个排列，这道题用第一个函数就ok。\n```cpp\n#include <iostream>\n#include <cstdio>\n#include <cstring>\nusing namespace std;\nchar s[1005];\nint length;\nint main()\n{\n\tgets(s);\n\tlength=strlen(s);\n\tnext_permutation(s,s+length);\n\tputs(s);\n\treturn 0;\n}\n```\n\n E 正文"}]};